/* =========================================================
   Shopper storefront (responsive: desktop + mobile, EN / VI)
   ========================================================= */
const B={};
VIEWS.buyer=dev=>{
  const r=S.r.buyer;const v=(B[r.n]||B.home)(r.p||{});
  const sb=dev==='mobile'?`<div class="statusbar"><span>9:41</span><span class="row g4 xs">5G ▮▮▮ 🔋</span></div>`:'';
  if(v.bare)return `${sb}<div class="vp">${v.body}</div>${v.sticky?`<div class="m-sticky m-only">${v.sticky}</div>`:''}${overlay('buyer')}`;
  return `${sb}<div class="vp">${bHeader(v.nav)}<div class="bmain">${v.body}</div>${bFooter()}</div>${v.sticky?`<div class="m-sticky m-only">${v.sticky}</div>`:''}${bTabbar(v.tab)}${overlay('buyer')}`;
};
const first=()=>S.buyer.name.split(' ')[0];
const gb=(n,p)=>`go('buyer','${n}',${J(p||{})})`;
const WM='ecomdemo<b>.</b>';

function bHeader(nav){const a=curAddr(),b=S.buyer,cc=cartCount(),r=S.r.buyer;
  const q=r.n==='search'?(r.p.q||''):'';const cat=r.n==='search'?(r.p.cat||''):'';
  const sform=m=>`<form class="sbar" onsubmit="event.preventDefault();doSearch(this)" role="search">${ic('search','sm')}<input name="q" value="${esc(q)}" placeholder="${L('Search products and stores','Tìm sản phẩm, cửa hàng')}" aria-label="${L('Search','Tìm kiếm')}" autocomplete="off">${m?'':`<select name="cat" aria-label="${L('Department','Danh mục')}"><option value="">${L('All','Tất cả')}</option>${CATS.map(c=>`<option value="${c.id}" ${cat===c.id?'selected':''}>${cn(c)}</option>`).join('')}</select>`}<button type="submit" class="go" aria-label="${L('Search','Tìm kiếm')}">${ic('chev','sm')}</button></form>`;
  const nl=(id,label,act)=>`<button class="${nav===id?'on':''}" onclick="${act}">${label}</button>`;
  return `<div class="announce"><div class="wrapx"><span class="d-only">${L('Free shipping on $35+ from each store · Support in English & Tiếng Việt','Miễn phí giao cho đơn từ $35 mỗi cửa hàng · Hỗ trợ tiếng Anh & tiếng Việt')}</span><span class="m-only">${L('Free shipping on $35+ · EN / VI support','Miễn phí giao từ $35 · Hỗ trợ EN / VI')}</span><button class="d-only" onclick="openAddr()">${ic('pin','sm')} ${L('Deliver to','Giao đến')} ${esc(a.city)} ${a.zip}</button></div></div>
  <header class="hdr"><div class="wrapx"><div class="hdr-row">
   <button class="iconbtn m-only" onclick="openMenu()" aria-label="Menu">${ic('menu')}</button>
   <button class="wordmark" onclick="go('buyer','home')" aria-label="EcomDemo home">${WM}</button>
   <nav class="navlinks d-only">${nl('shop',L('Shop','Mua sắm'),gb('search',{}))}${nl('pantry',L('Pantry','Thực phẩm'),gb('search',{cat:'pantry'}))}${nl('kitchen',L('Kitchen','Nhà bếp'),gb('search',{cat:'kitchen'}))}${nl('beauty',L('Beauty','Làm đẹp'),gb('search',{cat:'beauty'}))}${nl('deals',L('Deals','Ưu đãi'),gb('deals'))}</nav>
   <div class="grow d-only" style="display:flex;justify-content:center">${sform(false)}</div>
   <div class="hicons">
    <button class="hicon" onclick="setLang(S.lang==='en'?'vi':'en')" aria-label="${L('Change language','Đổi ngôn ngữ')}" title="English / Tiếng Việt" style="padding:0 4px"><span class="lang"><span class="${S.lang==='en'?'on':''}">EN</span><span class="${S.lang==='vi'?'on':''}">VI</span></span></button>
    <button class="hicon d-only" onclick="${b.signedIn?gb('account'):gb('signin')}">${ic('user')}<span>${b.signedIn?esc(first()):L('Sign in','Đăng nhập')}</span></button>
    <button class="hicon d-only" onclick="${gb('lists')}" aria-label="${L('Saved','Đã lưu')}">${ic('heart')}</button>
    <button class="hicon" onclick="${gb('cart')}" aria-label="${L('Cart','Giỏ hàng')}, ${cc}">${ic('cart')}${cc?`<span class="cnt">${cc}</span>`:''}<span class="d-only">${L('Cart','Giỏ')}</span></button>
   </div></div></div>
   <div class="m-only m-search">${sform(true)}</div></header>`}
function bFooter(){return `<footer class="bfoot"><div class="wrapx">
  <div class="big">${WM}</div>
  <div class="cols"><div><p class="md muted" style="max-width:360px">${L('A marketplace of verified US businesses, made for Vietnamese-American families and everyone who loves what they make.','Sàn thương mại của các doanh nghiệp Mỹ đã xác minh, dành cho gia đình người Việt và những ai yêu sản phẩm của họ.')}</p>
    <form class="news" onsubmit="event.preventDefault();toast(L('Subscribed. See you in your inbox.','Đã đăng ký nhận tin.'),'send')"><input class="input" placeholder="${L('Email for weekly picks','Email nhận gợi ý hằng tuần')}" style="border-radius:999px"><button class="btn ink">${L('Join','Đăng ký')}</button></form></div>
   <div><h4>${L('Shop','Mua sắm')}</h4>${CATS.slice(0,5).map(c=>`<button onclick="${gb('search',{cat:c.id})}">${cn(c)}</button>`).join('')}<button onclick="${gb('deals')}">${L("Today's deals",'Ưu đãi hôm nay')}</button></div>
   <div><h4>${L('Sell','Bán hàng')}</h4><button onclick="openSell()">${L('Sell on EcomDemo','Bán hàng trên EcomDemo')}</button><a>${L('Seller fees','Biểu phí')}</a><a>${L('Seller stories','Câu chuyện người bán')}</a></div>
   <div><h4>${L('Help','Hỗ trợ')}</h4><button onclick="${gb('orders')}">${L('Your orders','Đơn hàng')}</button><a>${L('Returns & refunds','Đổi trả & hoàn tiền')}</a><a>${L('A-to-z Guarantee','Bảo đảm A-Z')}</a><button onclick="setLang(S.lang==='en'?'vi':'en')">${S.lang==='en'?'Tiếng Việt':'English'}</button></div></div>
  <div class="base"><span>© 2026 EcomDemo · ${L('Prototype','Bản demo')}</span><span>${L('Terms','Điều khoản')} · ${L('Privacy','Quyền riêng tư')} · 🇺🇸 ${L('United States · USD','Hoa Kỳ · USD')}</span></div></div></footer>`}
function bTabbar(tab){const cc=cartCount();const t=(id,n,i,l,c)=>`<button class="${tab===id?'on':''}" onclick="${gb(n)}">${ic(i)}${c?`<span class="cnt">${c}</span>`:''}<span>${l}</span></button>`;
  return `<nav class="tabbar m-only">${t('home','home','home',L('Home','Trang chủ'))}${t('cats','categories','grid',L('Shop','Danh mục'))}${t('deals','deals','tag',L('Deals','Ưu đãi'))}${t('account','account','user',L('You','Tôi'))}${t('cart','cart','cart',L('Cart','Giỏ'),cc)}</nav>`}

function doSearch(f){const q=f.q.value.trim();const cat=f.cat?f.cat.value:'';UI.tmp.sload=Date.now();go('buyer','search',{q,cat});setTimeout(()=>{if(S.r.buyer.n==='search')render('buyer')},450)}
function openP(id){const r=S.buyer.recent;const i=r.indexOf(id);if(i>=0)r.splice(i,1);r.unshift(id);r.splice(8);UI.tmp.qty=1;go('buyer','product',{id})}
function openSell(){S.seller.onboard=S.seller.onboard.status?S.seller.onboard:{step:0,data:{},status:null};go('seller','onboard',{})}
function toggleList(pid){const l=S.buyer.list;const i=l.indexOf(pid);if(i>=0){l.splice(i,1);toast(L('Removed from saved','Đã bỏ khỏi danh sách'),'heart')}else{l.push(pid);toast(L('Saved for later','Đã lưu'),'heart')}render('buyer')}
function addToCart(pid,q=1,v){const p=P(pid);v=v??(p.variants[0]||'');const c=S.buyer.cart.find(x=>x.pid===pid&&x.v===v);if(c)c.q=Math.min(10,c.q+q);else S.buyer.cart.push({pid,v,q});
  toast(L('Added to cart','Đã thêm vào giỏ')+` · ${cartCount()} ${L('items','sản phẩm')}`,'cart');render('buyer')}
function etaStd(){return addBiz(Date.now(),(S.seller.settings.handling||1)+3)}
function etaExp(){return addBiz(Date.now(),2)}
function cutoffTxt(){const d=new Date();const end=new Date(d);end.setHours(14,0,0,0);if(d>end)end.setDate(end.getDate()+1);const m=Math.round((end-d)/MIN);return L(`${Math.floor(m/60)} h ${m%60} min`,`${Math.floor(m/60)} giờ ${m%60} phút`)}
function delivLine(p){const free=p.price>=S.fees.freeShipMin;return p.stock<=5?`<span class="dealc">${L(`Only ${p.stock} left`,`Chỉ còn ${p.stock}`)}</span>`:`${free?L('Free delivery','Giao miễn phí'):L('Delivery','Giao')} ${dayShort(etaStd())}`}
const verIc=()=>ic('badge');

/* ---------- product card ---------- */
function pcard(p,o={}){const inL=S.buyer.list.includes(p.id);const d=pct(p);const s=SL(p.seller);
  return `<div class="pc">
   <div class="media" onclick="openP('${p.id}')">${pimg(p,o.w||520)}
    ${d?`<span class="tag bdg deal">−${d}%</span>`:p.reviews?'':`<span class="tag bdg dark">${L('New','Mới')}</span>`}
    <button class="heart ${inL?'on':''}" onclick="event.stopPropagation();toggleList('${p.id}')" aria-label="${L('Save','Lưu')}">${ic('heart','sm')}</button>
    ${o.atc===false?'':`<button class="quick" onclick="event.stopPropagation();addToCart('${p.id}')" aria-label="${L('Add to cart','Thêm vào giỏ')}">${ic('plus','sm')}<span>${L('Quick add','Thêm nhanh')}</span></button>`}
   </div>
   <div class="b">
    <div class="seller">${esc(s?s.name:'')}${s&&s.verified?verIc():''}</div>
    <div class="t clamp2" onclick="openP('${p.id}')">${esc(pn(p))}</div>
    <div class="pr">${priceHTML(p.price)}${p.list>p.price?`<span class="list-price"><s>${money(p.list)}</s></span>`:''}</div>
    <div class="meta">${p.reviews?`<span class="stars" style="--v:${p.rating};font-size:11px"></span> ${p.rating} (${num(p.reviews)}) · `:''}${delivLine(p)}</div>
   </div></div>`}
const rail=(title,list,link,eyebrow,five)=>list.length?`<section class="sec"><div class="wrapx"><div class="sec-h"><div>${eyebrow?`<span class="eyebrow">${eyebrow}</span>`:''}<h2>${title}</h2></div>${link?`<a class="more" onclick="${link}">${L('View all','Xem tất cả')} ${ic('chev','sm')}</a>`:''}</div><div class="rail ${five?'five':''}">${list.map(p=>pcard(p)).join('')}</div></div></section>`:'';

/* ---------- Home ---------- */
B.home=()=>{const c=S.content;const V=visible();const pp=ids=>ids.map(P).filter(p=>p&&p.status==='active');
  const deals=V.filter(p=>pct(p)&&!p.flag).sort((a,b)=>pct(b)-pct(a));
  const best=V.filter(p=>!p.flag).sort((a,b)=>b.bought-a.bought).slice(0,10);
  const recent=pp(S.buyer.recent);
  const col=pp(['c1','k1','b1']);
  const tag=p=>{const s=SL(p.seller);return `<span class="tagpill">${mono(s)}<span class="ell"><b>${money(p.price)}</b> · ${esc(pn(p).split(/[,(]/)[0])}</span></span>`};
  const heroH=L(c.heroEn,c.heroVi);const hw=heroH.split(' ');const heroHTML=esc(hw.slice(0,-2).join(' '))+' <em>'+esc(hw.slice(-2).join(' '))+'</em>';
  const makers=SELLERS.filter(s=>s.verified).slice(0,3).map(s=>SL(s.id));
  const feat=(p,eye,title,sub,cta,act,cls='')=>`<button class="feature ${cls}" onclick="${act}">${pimg(p,1000)}<span class="eyebrow">${eye}</span><h3>${title}</h3>${sub?`<p>${sub}</p>`:''}<span class="btn sm">${cta} ${ic('chev','sm')}</span></button>`;
  return{tab:'home',body:`
  <div class="wrapx"><section class="hero">
   <div><span class="eyebrow">${esc(L(c.eyebrowEn,c.eyebrowVi))}</span><h1>${heroHTML}</h1><p class="lead">${esc(L(c.subEn,c.subVi))}</p>
    <div class="ctas"><button class="btn ink lg" onclick="${gb('deals')}">${esc(L(c.ctaEn,c.ctaVi))}</button><button class="btn lg" onclick="${gb('search',{cat:'pantry'})}">${L('Explore the pantry','Khám phá thực phẩm Việt')}</button></div>
    <div class="stats"><div><b>${SELLERS.filter(s=>s.verified).length*15}+</b><span>${L('verified US businesses','doanh nghiệp đã xác minh')}</span></div><div><b>4.8★</b><span>${L('average store rating','đánh giá trung bình')}</span></div><div><b>EN · VI</b><span>${L('shopping & support','mua sắm & hỗ trợ')}</span></div></div></div>
   <div class="collage">${col.map(p=>`<button onclick="openP('${p.id}')">${pimg(p,900)}${tag(p)}</button>`).join('')}<div class="stamp"><span>${L('Up to','Đến')}<b>−${Math.max(...deals.map(pct))}%</b>${L('this week','tuần này')}</span></div></div>
  </section></div>
  <div class="marquee" aria-hidden="true"><div class="track">${Array(2).fill([L('Cà phê sữa đá, at home','Cà phê sữa đá tại nhà'),L('Verified US businesses','Doanh nghiệp đã xác minh'),L('Free 30-day returns','Đổi trả miễn phí 30 ngày'),L('Lunar New Year gifting','Quà Tết'),L('Shop in Tiếng Việt','Mua sắm bằng tiếng Việt'),L('A-to-z Guarantee','Bảo đảm A-Z')].map(t=>`<span>${t}</span>`).join('')).join('')}</div></div>
  <section class="sec"><div class="wrapx"><div class="sec-h"><div><span class="eyebrow">${L('Departments','Danh mục')}</span><h2>${L('Shop by <em>category</em>','Mua theo <em>danh mục</em>')}</h2></div><a class="more" onclick="${gb('categories')}">${L('All departments','Tất cả danh mục')} ${ic('chev','sm')}</a></div>
   <div class="cats">${CATS.map(ct=>{const p=V.find(x=>x.cat===ct.id&&!x.flag);return `<button class="cat" onclick="${gb('search',{cat:ct.id})}">${p?pimg(p,300):'<span class="img"></span>'}<span>${cn(ct)}<small>${V.filter(x=>x.cat===ct.id).length} ${L('items','sản phẩm')}</small></span></button>`}).join('')}</div></div></section>
  ${rail(L("Today's <em>deals</em>",'Ưu đãi <em>hôm nay</em>'),deals,gb('deals'),L('Prices checked against the last 90 days','Giá đã đối chiếu 90 ngày qua'),true)}
  <section class="sec"><div class="wrapx"><div class="features">
   ${feat(P('c1'),L('Vietnamese pantry','Thực phẩm Việt'),L('A taste of home, delivered','Hương vị quê nhà, giao tận nơi'),L('Robusta from the highlands, Thai Nguyen tea, Binh Phuoc cashews. Roasted and packed by US businesses.','Robusta Tây Nguyên, trà Thái Nguyên, hạt điều Bình Phước, được rang và đóng gói tại Mỹ.'),L('Explore the pantry','Khám phá'),gb('search',{cat:'pantry'}),'tall')}
   <div class="stack">${feat(P('f3'),L('Ships from January 5','Giao từ ngày 5/1'),L('Lunar New Year gifting','Quà Tết sum vầy'),'',L('Pre-order baskets','Đặt trước giỏ quà'),`openP('f3')`)}${feat(P('k2'),L('Kitchen','Nhà bếp'),L('Everyday kitchen, upgraded','Bếp nhà, nâng cấp'),'',L('Shop kitchen','Xem đồ bếp'),gb('search',{cat:'kitchen'}))}</div>
  </div></div></section>
  <section class="sec"><div class="wrapx"><div class="sec-h"><div><span class="eyebrow">${L('Most loved','Được yêu thích')}</span><h2>${L('Best <em>sellers</em>','Bán <em>chạy nhất</em>')}</h2></div><a class="more" onclick="${gb('search',{sort:'rating'})}">${L('View all','Xem tất cả')} ${ic('chev','sm')}</a></div><div class="pgrid">${best.map(p=>pcard(p)).join('')}</div></div></section>
  <section class="sec"><div class="wrapx"><div class="sec-h"><div><span class="eyebrow">${L('Meet the makers','Gặp gỡ người bán')}</span><h2>${L('Real businesses, <em>verified</em>','Doanh nghiệp thật, <em>đã xác minh</em>')}</h2></div></div>
   <div class="makers">${makers.map(s=>`<button class="maker" onclick="${gb('store',{id:s.id})}"><div class="row g12">${mono(s)}<div><h4>${esc(s.name)}</h4><div class="xs faint">${esc(s.city)} · ${L('since','từ')} ${s.since}</div></div></div><p class="sm muted clamp3">${esc(L(s.about,s.aboutVi))}</p><div class="row g8 xs"><span class="bdg info">${verIc()} ${L('Verified business','Đã xác minh')}</span><span class="faint">★ ${s.rating} · ${num(s.count)} ${L('ratings','đánh giá')}</span></div><div class="thumbs">${V.filter(p=>p.seller===s.id).slice(0,3).map(p=>pimg(p,200)).join('')}</div></button>`).join('')}</div></div></section>
  <section class="sec"><div class="wrapx"><div class="sell-band"><div><span class="eyebrow" style="color:rgba(245,242,236,.6)">${L('For businesses','Dành cho doanh nghiệp')}</span><h3 class="mt12">${L('Sell to Vietnamese-American <em>households</em> nationwide','Bán hàng đến <em>gia đình người Việt</em> khắp nước Mỹ')}</h3><p>${L('Verified business stores, transparent referral fees, payouts every 14 days and listing tools in English and Tiếng Việt.','Cửa hàng doanh nghiệp đã xác minh, phí minh bạch, thanh toán mỗi 14 ngày, công cụ đăng bán song ngữ.')}</p><button class="btn lg mt24" onclick="openSell()">${L('Start selling','Bắt đầu bán hàng')} ${ic('chev','sm')}</button></div>
   <div class="facts"><div><b>8–15%</b><span>${L('referral fee, nothing hidden','phí giới thiệu, không phí ẩn')}</span></div><div><b>14 ${L('days','ngày')}</b><span>${L('payout cycle','chu kỳ thanh toán')}</span></div><div><b>1 ${L('day','ngày')}</b><span>${L('business verification','xác minh doanh nghiệp')}</span></div><div><b>2</b><span>${L('languages for every listing','ngôn ngữ cho mỗi sản phẩm')}</span></div></div></div></div></section>
  ${rail(L('Recently <em>viewed</em>','Đã <em>xem gần đây</em>'),recent,null,L('Pick up where you left off','Tiếp tục mua sắm'))}
  <section class="sec"><div class="wrapx"><div class="promise">${[['badge',L('Verified businesses','Doanh nghiệp đã xác minh'),L('Every seller passes EIN, identity and bank checks.','Mọi người bán đều được xác minh EIN, danh tính và ngân hàng.')],['shield',L('A-to-z Guarantee','Bảo đảm A-Z'),L('The item you ordered, or your money back.','Nhận đúng hàng hoặc được hoàn tiền.')],['return',L('Free 30-day returns','Đổi trả miễn phí 30 ngày'),L('Drop off at any UPS Store. No box needed.','Gửi tại UPS Store, không cần hộp.')],['globe',L('English & Tiếng Việt','Tiếng Anh & Tiếng Việt'),L('Shop and get help in either language.','Mua sắm và được hỗ trợ bằng cả hai ngôn ngữ.')]].map(([i,t,s])=>`<div>${ic(i)}<b>${t}</b><span>${s}</span></div>`).join('')}</div></div></section>`}};

/* ---------- Categories ---------- */
B.categories=()=>({tab:'cats',nav:'shop',body:`<div class="wrapx"><h1 class="pagetitle">${L('All <em>departments</em>','Tất cả <em>danh mục</em>')}</h1>
  <div class="pgrid">${CATS.map(c=>{const p=visible().find(x=>x.cat===c.id&&!x.flag);return `<button class="pc" onclick="${gb('search',{cat:c.id})}"><div class="media">${p?pimg(p,500):'<span class="img" style="aspect-ratio:4/5"></span>'}</div><div class="b"><div class="serif" style="font-size:22px">${cn(c)}</div><div class="meta">${visible().filter(x=>x.cat===c.id).length} ${L('items','sản phẩm')}</div></div></button>`}).join('')}</div></div>`});

/* ---------- Search ---------- */
const PRICE_BANDS=[['0-25','Under $25','Dưới $25'],['25-50','$25 to $50','$25 – $50'],['50-100','$50 to $100','$50 – $100'],['100-9999','$100 & above','Từ $100']];
function searchList(p){const f=p.f||{};const q=norm(p.q);
  let list=visible().filter(x=>{if(p.cat&&x.cat!==p.cat)return false;if(p.seller&&x.seller!==p.seller)return false;
    if(q){const hay=norm(x.en+' '+x.vi+' '+x.brand+' '+cn(x.cat)+' '+CAT(x.cat).en+' '+sellerName(x.seller));if(!q.split(/\s+/).every(w=>hay.includes(w)||hay.includes(w.replace(/s$/,''))))return false}
    if(f.rating&&x.rating<f.rating)return false;
    if(f.price){const [a,b]=f.price.split('-').map(Number);if(x.price<a||x.price>b)return false}
    if(f.deal&&!pct(x))return false;
    if(f.free&&x.price<S.fees.freeShipMin)return false;
    if(f.state&&SL(x.seller).state!==f.state)return false;
    if(f.verified&&!SL(x.seller).verified)return false;
    return true});
  const s=p.sort||'featured';
  if(s==='featured')list.sort((a,b)=>(b.rating*Math.log(b.reviews+2)+(b.flag?-9:0))-(a.rating*Math.log(a.reviews+2)+(a.flag?-9:0)));
  if(s==='low')list.sort((a,b)=>a.price-b.price);if(s==='high')list.sort((a,b)=>b.price-a.price);
  if(s==='rating')list.sort((a,b)=>b.rating-a.rating);if(s==='new')list.sort((a,b)=>b.created-a.created);
  return list}
function setF(k,v){const p=S.r.buyer.p;const f={...(p.f||{})};if(f[k]===v||v==null)delete f[k];else f[k]=v;go('buyer','search',{...p,f},true);if(UI.ov.buyer)UI.ov.buyer=null}
function facetsHTML(p){const f=p.f||{};const opt=(on,label,act)=>`<button class="${on?'on':''}" onclick="${act}"><span class="chk ${on?'on':''}">${on?ic('check','sm'):''}</span>${label}</button>`;
  const states=[['CA','California'],['TX','Texas'],['WA','Washington'],['VA','Virginia']];
  return `<div class="facets">
   <h4>${L('Department','Danh mục')}</h4>${p.cat?`<button onclick="go('buyer','search',{...S.r.buyer.p,cat:''},true)">← ${L('All departments','Tất cả danh mục')}</button><button class="on">${cn(p.cat)}</button>`:CATS.map(c=>`<button onclick="go('buyer','search',{...S.r.buyer.p,cat:'${c.id}'},true)">${cn(c)}</button>`).join('')}
   <h4>${L('Rating','Đánh giá')}</h4>${[4,3].map(n=>opt(f.rating===n,`${stars(n)} ${L('& up','trở lên')}`,`setF('rating',${n})`)).join('')}
   <h4>${L('Price','Giá')}</h4>${PRICE_BANDS.map(([k,e,v])=>opt(f.price===k,L(e,v),`setF('price','${k}')`)).join('')}
   <div class="row g4 mt8"><input class="input pmin" style="min-height:36px;width:76px" placeholder="$ Min" inputmode="decimal"><input class="input pmax" style="min-height:36px;width:76px" placeholder="$ Max" inputmode="decimal"><button class="btn sm" onclick="const f=this.closest('.facets');setF('price',(+f.querySelector('.pmin').value||0)+'-'+(+f.querySelector('.pmax').value||9999))">${L('Go','Lọc')}</button></div>
   <h4>${L('Offers','Ưu đãi')}</h4>${opt(f.deal,L('On sale','Đang giảm giá'),"setF('deal',1)")}${opt(f.free,L('Free shipping eligible','Miễn phí giao hàng'),"setF('free',1)")}
   <h4>${L('Ships from','Giao từ')}</h4>${states.map(([k,n])=>opt(f.state===k,n,`setF('state','${k}')`)).join('')}
   <h4>${L('Seller','Người bán')}</h4>${opt(f.verified,L('Verified businesses only','Chỉ doanh nghiệp đã xác minh'),"setF('verified',1)")}
  </div>`}
B.search=p=>{const list=searchList(p);const f=p.f||{};const nf=Object.keys(f).length;const loading=UI.tmp.sload&&Date.now()-UI.tmp.sload<420;
  const title=p.q?`“<em>${esc(p.q)}</em>”`:p.cat?cn(p.cat):L('Shop <em>everything</em>','Tất cả <em>sản phẩm</em>');
  const sorts=[['featured','Featured','Nổi bật'],['low','Price: low to high','Giá: thấp đến cao'],['high','Price: high to low','Giá: cao đến thấp'],['rating','Top rated','Đánh giá cao nhất'],['new','Newest','Mới nhất']];
  const chips=[f.rating&&[L(`${f.rating}★ & up`,`${f.rating}★ trở lên`),"setF('rating')"],f.price&&['$'+f.price.replace('-',' – $').replace('$9999','+'),"setF('price')"],f.deal&&[L('On sale','Giảm giá'),"setF('deal')"],f.free&&[L('Free shipping','Miễn phí giao'),"setF('free')"],f.state&&[L('Ships from ','Giao từ ')+f.state,"setF('state')"],f.verified&&[L('Verified','Đã xác minh'),"setF('verified')"]].filter(Boolean);
  const navMap={pantry:'pantry',kitchen:'kitchen',beauty:'beauty'};
  return{tab:p.cat&&!p.q?'cats':'',nav:p.q?'':navMap[p.cat]||'shop',body:`<div class="wrapx">
  <div class="srp-head"><div><span class="eyebrow">${p.q?L('Search results','Kết quả tìm kiếm'):L('Department','Danh mục')}</span><h1 class="mt8">${title}</h1><div class="sm muted mt8">${list.length} ${L(list.length===1?'product':'products','sản phẩm')}</div></div>
   <div class="row g8"><button class="btn m-only" onclick="openFilters()">${ic('filter','sm')} ${L('Filters','Bộ lọc')}${nf?` · ${nf}`:''}</button><select class="select sortsel" aria-label="${L('Sort','Sắp xếp')}" onchange="go('buyer','search',{...S.r.buyer.p,sort:this.value},true)">${sorts.map(([k,e,v])=>`<option value="${k}" ${(p.sort||'featured')===k?'selected':''}>${L(e,v)}</option>`).join('')}</select></div></div>
  <div class="srp"><aside class="d-only">${facetsHTML(p)}</aside>
   <div>${chips.length?`<div class="chips mb16">${chips.map(([l,a])=>`<button class="chip on" onclick="${a}">${l} ${ic('x','sm')}</button>`).join('')}<button class="chip" onclick="go('buyer','search',{q:S.r.buyer.p.q||'',cat:S.r.buyer.p.cat||''},true)">${L('Clear all','Xóa lọc')}</button></div>`:''}
    ${loading?`<div class="res-grid">${Array(8).fill(0).map(()=>`<div class="pc"><div class="skel" style="aspect-ratio:4/5"></div><div class="b"><div class="skel" style="height:12px;width:40%;border-radius:6px"></div><div class="skel" style="height:14px;border-radius:6px"></div><div class="skel" style="height:16px;width:30%;border-radius:6px"></div></div></div>`).join('')}</div>`
    :list.length?`<div class="res-grid">${list.map(x=>pcard(x)).join('')}</div>`
    :`<div class="empty"><div class="art">${ic('search','xl')}</div><h3 class="serif" style="font-size:26px">${L('Nothing found','Không tìm thấy')}</h3><div>${L('Try a broader word, or browse a department.','Thử từ khóa chung hơn hoặc xem theo danh mục.')}</div><button class="btn ink" onclick="${gb('search',{})}">${L('See all products','Xem tất cả sản phẩm')}</button></div>`}
   </div></div></div>`}};
function openFilters(){openOv('buyer',()=>`<div class="modal">${mHead('buyer',L('Filters','Bộ lọc'))}<div class="modal-b">${facetsHTML(S.r.buyer.p)}</div><div class="modal-f"><button class="btn" onclick="go('buyer','search',{q:S.r.buyer.p.q||'',cat:S.r.buyer.p.cat||''},true)">${L('Clear','Xóa')}</button><button class="btn ink" onclick="closeOv('buyer')">${L('Show','Xem')} ${searchList(S.r.buyer.p).length} ${L('results','kết quả')}</button></div></div>`)}

/* ---------- Deals ---------- */
B.deals=p=>{const list=visible().filter(x=>pct(x)&&!x.flag&&(!p.cat||x.cat===p.cat)).sort((a,b)=>pct(b)-pct(a));
  return{tab:'deals',nav:'deals',body:`<div class="wrapx"><div class="srp-head"><div><span class="eyebrow">${L('Updated daily','Cập nhật mỗi ngày')}</span><h1 class="mt8">${L("Today's <em>deals</em>",'Ưu đãi <em>hôm nay</em>')}</h1><div class="sm muted mt8">${L('Every discount is measured against the median price of the last 90 days.','Mức giảm được tính trên giá trung vị 90 ngày qua.')}</div></div></div>
  <div class="chips mb16" style="margin-top:-4px"><button class="chip ${!p.cat?'on':''}" onclick="go('buyer','deals',{},true)">${L('All deals','Tất cả')}</button>${CATS.filter(c=>visible().some(x=>x.cat===c.id&&pct(x))).map(c=>`<button class="chip ${p.cat===c.id?'on':''}" onclick="go('buyer','deals',{cat:'${c.id}'},true)">${cn(c)}</button>`).join('')}</div>
  <div class="pgrid mt24">${list.map(x=>pcard(x)).join('')}</div></div>`}};

/* ---------- Product detail ---------- */
function histOf(p){const r=p.rating;const five=Math.round(Math.min(92,Math.max(30,(r-3.4)*58)));const four=Math.round((100-five)*.55);const three=Math.round((100-five-four)*.5);const one=Math.round((100-five-four-three)*.6);return[five,four,three,100-five-four-three-one,one]}
B.product=p=>{const x=P(p.id);if(!x||x.status==='removed')return{body:`<div class="wrapx"><div class="empty"><div class="art">${ic('box','xl')}</div><h3 class="serif" style="font-size:26px">${L('This item is no longer available','Sản phẩm không còn bán')}</h3><button class="btn ink" onclick="${gb('home')}">${L('Continue shopping','Tiếp tục mua sắm')}</button></div></div>`};
  const s=SL(x.seller);const ph=photos(x);const v=p.v??(x.variants[0]||'');const q=UI.tmp.qty||1;const d=pct(x);
  const rv=S.reviews.filter(r=>r.pid===x.id).sort((a,b)=>a.days-b.days);const qs=S.questions.filter(z=>z.pid===x.id);
  const fbt=[x,...visible().filter(y=>y.id!==x.id&&(y.seller===x.seller||y.cat===x.cat)&&!y.flag).slice(0,2)];const fbtSum=fbt.reduce((a,y)=>a+y.price,0);
  const related=visible().filter(y=>y.id!==x.id&&y.cat===x.cat&&!y.flag).concat(visible().filter(y=>y.cat!==x.cat&&!y.flag).slice(0,6));
  const free=x.price*q>=S.fees.freeShipMin;const a=curAddr();const h=histOf(x);const bul=BULLETS[x.cat]||[];
  const varLabel={kitchen:L('Color','Màu'),electronics:L('Color','Màu'),fashion:L('Size','Kích cỡ'),coffee:L('Grind','Loại'),home:L('Option','Tùy chọn'),baby:L('Color','Màu')}[x.cat]||L('Option','Tùy chọn');
  const maxQ=Math.min(10,x.stock);
  return{body:`<div class="wrapx"><div class="crumbs"><a onclick="${gb('home')}">${L('Home','Trang chủ')}</a>/<a onclick="${gb('search',{cat:x.cat})}">${cn(x.cat)}</a>/<span>${esc(x.brand)}</span></div>
  <div class="pdp">
   <div><div class="gal d-only" style="display:grid">${ph.map((id,i)=>img(id,i?700:1200,'','',i?875:960)).join('')}</div><div class="m-gal m-only" style="display:flex">${ph.map(id=>img(id,700,'','',875)).join('')}</div></div>
   <div class="pinfo">
    <button class="sellerchip" onclick="${gb('store',{id:s.id})}">${mono(s,'sm')}<span>${esc(s.name)}</span>${s.verified?verIc():''}</button>
    <h1>${esc(pn(x))}</h1>
    <div class="row wrap g12 mt12 sm muted">${stars(x.rating)}<span><b style="color:var(--ink)">${x.rating}</b> · ${num(x.reviews)} ${L('ratings','đánh giá')}</span>${x.bought?`<span>· ${boughtTxt(x.bought)}</span>`:''}</div>
    <div class="pricebox">${priceHTML(x.price,'l')}${x.list>x.price?`<span class="list-price md"><s>${money(x.list)}</s></span><span class="bdg deal">−${d}%</span>`:''}</div>
    <div class="sm muted mt8">${L('Or 4 interest-free payments of','Hoặc trả góp 4 kỳ 0% lãi, mỗi kỳ')} <b style="color:var(--ink)">${money(x.price/4)}</b> ${L('with Affirm','qua Affirm')}</div>
    <div class="note mt16">${ic('chart','sm')}<span>${L('Lowest price in the last 30 days:','Giá thấp nhất 30 ngày qua:')} <b style="color:var(--ink)">${money(Math.min(x.low30,x.price))}</b>${x.list>x.price?' · '+L('list price verified against 90-day history','giá niêm yết đã đối chiếu lịch sử 90 ngày'):''}</span></div>
    ${x.variants.length?`<div class="mt24"><div class="sm mb8">${varLabel}: <b>${esc(v)}</b></div><div class="vsel">${x.variants.map(o=>`<button class="${o===v?'on':''}" onclick="setP('buyer',{v:${J(o)}})">${esc(o)}</button>`).join('')}</div></div>`:''}
    <div class="buy-row"><span class="stepper"><button onclick="UI.tmp.qty=Math.max(1,(UI.tmp.qty||1)-1);render('buyer')" aria-label="${L('Decrease','Giảm')}">${ic('minus','sm')}</button><span>${q}</span><button onclick="UI.tmp.qty=Math.min(${maxQ},(UI.tmp.qty||1)+1);render('buyer')" aria-label="${L('Increase','Tăng')}">${ic('plus','sm')}</button></span><button class="btn ink lg" onclick="addToCart('${x.id}',UI.tmp.qty||1,${J(v)})">${L('Add to cart','Thêm vào giỏ')}</button></div>
    <button class="btn buy lg block mt8" onclick="buyNow('${x.id}',${J(v)})">${L('Buy now','Mua ngay')}</button>
    <div class="deliv"><div>${ic('truck')}<span><b>${free?L('Free delivery','Giao miễn phí'):money(S.fees.stdShip)+' '+L('delivery','phí giao')} ${fmtDate(etaStd())}</b><br><span class="muted">${L('Or fastest','Hoặc nhanh nhất')} ${fmtDate(etaExp())} · ${L('order within','đặt trong')} <span class="okc">${cutoffTxt()}</span></span></span></div>
     <div>${ic('pin')}<span>${L('Deliver to','Giao đến')} ${esc(first())}, ${esc(a.city)} ${a.zip} · <a class="lnk" onclick="openAddr()">${L('Change','Đổi')}</a><br><span class="${x.stock<=5?'dealc':'okc'}">${x.stock<=5?L(`Only ${x.stock} left in stock`,`Chỉ còn ${x.stock} sản phẩm`):L('In stock','Còn hàng')}</span> · <span class="muted">${L('Ships from','Giao từ')} ${esc(s.city)}</span></span></div></div>
    <div class="assure">${[['return',L('Free 30-day returns','Đổi trả miễn phí 30 ngày')],['badge',L('Verified business','Doanh nghiệp đã xác minh')],['shield',L('A-to-z Guarantee','Bảo đảm A-Z')],['lock',L('Secure checkout','Thanh toán an toàn')]].map(([i,t])=>`<span>${ic(i)}${t}</span>`).join('')}</div>
    <div class="row g8 mt16"><button class="btn sm" onclick="toggleList('${x.id}')">${ic('heart','sm')} ${S.buyer.list.includes(x.id)?L('Saved','Đã lưu'):L('Save','Lưu')}</button><button class="btn sm" onclick="toast(L('Link copied','Đã sao chép liên kết'),'send')">${ic('send','sm')} ${L('Share','Chia sẻ')}</button></div>
    <div class="acc">
     <details open><summary>${L('About this item','Thông tin sản phẩm')}</summary><div class="in"><ul class="bul">${bul.map(b=>`<li>${esc(L(b[0],b[1]))}</li>`).join('')}</ul></div></details>
     <details><summary>${L('Details','Chi tiết')}</summary><div class="in"><table class="spec"><tr><td>${L('Brand','Thương hiệu')}</td><td>${esc(x.brand)}</td></tr><tr><td>${L('Category','Danh mục')}</td><td>${cn(x.cat)}</td></tr><tr><td>${L('Item weight','Trọng lượng')}</td><td>${x.weight} lb</td></tr><tr><td>UPC</td><td>${x.upc}</td></tr><tr><td>SKU</td><td>${x.sku}</td></tr><tr><td>${L('First available','Ngày mở bán')}</td><td>${shortDate(x.created)}</td></tr></table></div></details>
     <details><summary>${L('Shipping & returns','Giao hàng & đổi trả')}</summary><div class="in sm muted">${L(`Free standard shipping on $${S.fees.freeShipMin}+ from this store, otherwise ${money(S.fees.stdShip)}. Expedited 2-day ${money(S.fees.expShip)}. Return within 30 days at any UPS Store, free for seller-fault returns.`,`Miễn phí giao tiêu chuẩn cho đơn từ $${S.fees.freeShipMin} của cửa hàng này, nếu không là ${money(S.fees.stdShip)}. Giao nhanh 2 ngày ${money(S.fees.expShip)}. Đổi trả trong 30 ngày tại UPS Store.`)}</div></details>
     <details><summary>${L('About the seller','Về người bán')}</summary><div class="in sm muted">${esc(L(s.about,s.aboutVi))}<div class="mt8"><a class="lnk" onclick="${gb('store',{id:s.id})}">${L('Visit store','Ghé cửa hàng')}</a></div></div></details>
    </div>
   </div>
  </div>
  <section class="below"><h2>${L('Frequently bought together','Thường được mua cùng')}</h2>
   <div class="fbt">${fbt.map((y,i)=>`${i?'<span class="plus">+</span>':''}<button onclick="openP('${y.id}')" title="${esc(pn(y))}">${pimg(y,260)}</button>`).join('')}<div class="col" style="gap:8px;margin-left:auto"><div class="sm muted">${L('Total for all','Tổng cộng')} ${fbt.length}</div><div class="serif" style="font-size:30px">${money(fbtSum)}</div><button class="btn ink" onclick="${fbt.map(y=>`addToCart('${y.id}')`).join(';')}">${L(`Add all ${fbt.length} to cart`,`Thêm cả ${fbt.length} vào giỏ`)}</button></div></div></section>
  <section class="below"><div class="reviews">
   <div><h2>${L('Reviews','Đánh giá')}</h2><div class="bigscore">${x.rating}</div><div class="mt8">${stars(x.rating,'lg')}</div><div class="sm muted mt8">${num(x.reviews)} ${L('global ratings','lượt đánh giá')}</div>
    <div class="hist">${h.map((v,i)=>`<span>${5-i} ★</span><div class="bar"><i style="width:${v}%"></i></div><span>${v}%</span>`).join('')}</div>
    <button class="btn block mt24" onclick="${gb('review',{id:x.id})}">${L('Write a review','Viết đánh giá')}</button></div>
   <div>${rv.map(r=>{const tr=UI.tmp.tr&&UI.tmp.tr[r.id];const showVi=(r.lang==='vi')!==!!tr;return `<div class="rv"><div class="row between"><div class="row g8"><span class="avatar">${esc(r.name[0])}</span><span class="sm"><b>${esc(r.name)}</b><br><span class="faint xs">${shortDate(Date.now()-r.days*DAY)}${r.variant?` · ${esc(r.variant)}`:''}</span></span></div>${r.verified?`<span class="vp-tag">${ic('check','sm')} ${L('Verified purchase','Đã mua hàng')}</span>`:''}</div>
     <div class="mt12">${stars(r.stars)}</div><h4 class="mt8">${esc(showVi?r.titleVi:r.title)}</h4>
     <p class="md muted mt8">${esc(showVi?r.textVi:r.text)}</p>
     <div class="row g12 mt12 xs muted">${r.lang==='vi'||S.lang==='vi'?`<a class="lnk" onclick="UI.tmp.tr=UI.tmp.tr||{};UI.tmp.tr['${r.id}']=!UI.tmp.tr['${r.id}'];render('buyer')">${tr?L('See original','Xem bản gốc'):(r.lang==='vi'?L('Translate to English','Dịch sang tiếng Anh'):L('Translate to Vietnamese','Dịch sang tiếng Việt'))}</a>${r.lang==='vi'?`<span>${L('Written in Vietnamese','Viết bằng tiếng Việt')}</span>`:''}`:''}<span>${r.helpful} ${L('found this helpful','người thấy hữu ích')}</span><button class="btn sm" onclick="this.textContent='${L('Thanks!','Cảm ơn!')}'">${L('Helpful','Hữu ích')}</button></div></div>`}).join('')}</div></div></section>
  <section class="below" style="max-width:860px"><h2>${L('Questions & answers','Hỏi & đáp')}</h2>
   <div class="row g8"><input class="input" id="askq" placeholder="${L('Ask the seller about this product','Đặt câu hỏi cho người bán')}" style="border-radius:999px"><button class="btn ink" onclick="askQ('${x.id}')">${L('Ask','Gửi')}</button></div>
   <div class="mt8">${qs.map(z=>`<div class="qa"><div class="q">${esc(z.q)}</div><div class="mt4 muted">${z.a?`${esc(z.a)} <span class="xs faint">· ${esc(z.by)}, ${ago(z.t)}</span>`:`<span class="faint">${L('Waiting for the seller to answer.','Đang chờ người bán trả lời.')}</span>`}</div></div>`).join('')||`<p class="muted sm mt12">${L('No questions yet.','Chưa có câu hỏi.')}</p>`}</div></section></div>
  ${rail(L('You may also <em>like</em>','Có thể bạn <em>thích</em>'),related.slice(0,12),null,L('Related','Liên quan'))}`,
  sticky:`<div class="grow">${priceHTML(x.price,'s')}<div class="xs ${free?'okc':'muted'}">${free?L('Free delivery','Giao miễn phí'):money(S.fees.stdShip)+' '+L('delivery','phí giao')} ${dayShort(etaStd())}</div></div><button class="btn ink" onclick="addToCart('${x.id}',UI.tmp.qty||1,${J(v)})">${L('Add to cart','Thêm vào giỏ')}</button><button class="btn buy" onclick="buyNow('${x.id}',${J(v)})">${L('Buy now','Mua ngay')}</button>`}};
function buyNow(pid,v){const c=S.buyer.cart.find(x=>x.pid===pid&&x.v===v);if(!c)S.buyer.cart.push({pid,v,q:UI.tmp.qty||1});UI.tmp.only=pid;go('buyer',S.buyer.signedIn?'checkout':'signin',S.buyer.signedIn?{}:{next:'checkout'})}
function askQ(pid){const el=$('.frame[data-role="buyer"] #askq');const v=el&&el.value.trim();if(!v){toast(L('Type a question first','Hãy nhập câu hỏi'),'alert');return}
  S.questions.unshift({pid,q:v,a:null,by:null,t:Date.now()});notify('seller',`New customer question on <b>${esc(P(pid).en.split(',')[0])}</b>`,['feedback',{}]);
  toast(L('Question sent to the seller. We will email you the answer.','Đã gửi câu hỏi cho người bán, câu trả lời sẽ gửi qua email.'));render('buyer');if(onStage('seller'))render('seller')}

/* ---------- Store ---------- */
B.store=p=>{const s=SL(p.id);const all=visible().filter(x=>x.seller===s.id);const list=all.filter(x=>!p.q||norm(x.en+x.vi).includes(norm(p.q)));
  return{body:`<div class="wrapx"><div class="store-cover" style="--h:${s.hue}">${all[0]?pimg(all[0],1400):''}</div><div class="store-head">${mono(s,'lg')}<div class="grow" style="padding-bottom:6px"><h1>${esc(s.name)}</h1><div class="row wrap g8 sm mt8">${s.verified?`<span class="bdg info">${verIc()} ${L('Verified US business','Doanh nghiệp Mỹ đã xác minh')}</span>`:`<span class="bdg warn">${L('Not verified','Chưa xác minh')}</span>`}<span class="muted">★ ${s.rating} (${num(s.count)}) · ${esc(s.city)} · ${L('since','từ')} ${s.since}</span></div></div></div>
  <div class="grid c-main mt32" style="align-items:start;gap:40px"><div><div class="row between mb16 wrap g12"><h2 class="serif" style="font-size:30px">${L('All products','Tất cả sản phẩm')} <span class="faint" style="font-size:20px">${list.length}</span></h2><form class="sbar" style="max-width:280px;height:42px" onsubmit="event.preventDefault();setP('buyer',{q:this.q.value})">${ic('search','sm')}<input name="q" value="${esc(p.q||'')}" placeholder="${L('Search this store','Tìm trong cửa hàng')}"></form></div><div class="pgrid">${list.map(x=>pcard(x)).join('')||`<div class="empty">${L('No products','Không có sản phẩm')}</div>`}</div></div>
   <div class="panel bd"><span class="eyebrow">${L('About','Giới thiệu')}</span><p class="md mt12">${esc(L(s.about,s.aboutVi))}</p><div class="hr"></div>
    <div class="kv sm"><span>${L('Business name','Tên pháp lý')}</span><b>${esc(s.legal)}</b></div><div class="kv sm"><span>${L('Location','Địa chỉ')}</span><span>${esc(s.city)}</span></div><div class="kv sm"><span>${L('Positive feedback','Phản hồi tích cực')}</span><b class="okc">${Math.round(s.rating*20-2)}%</b></div><div class="kv sm"><span>${L('Ships within','Gửi hàng trong')}</span><span>${L('1 business day','1 ngày làm việc')}</span></div>
    <p class="xs faint mt16">${L('Identity verified by EcomDemo through EIN, beneficial owner ID and bank account checks.','Danh tính được EcomDemo xác minh qua EIN, giấy tờ chủ sở hữu và tài khoản ngân hàng.')}</p></div></div></div>`}};

/* ---------- Cart ---------- */
function cartGroups(onlyPid){const items=S.buyer.cart.filter(c=>P(c.pid)&&P(c.pid).status==='active'&&(!onlyPid||c.pid===onlyPid));const g={};
  items.forEach(c=>{const p=P(c.pid);(g[p.seller]=g[p.seller]||{seller:p.seller,items:[],sub:0}).items.push(c);g[p.seller].sub+=p.price*c.q});return Object.values(g)}
function cartQty(pid,v,d){const c=S.buyer.cart.find(x=>x.pid===pid&&x.v===v);if(!c)return;c.q+=d;if(c.q<=0){S.buyer.cart.splice(S.buyer.cart.indexOf(c),1);toast(L('Removed from cart','Đã xóa khỏi giỏ'),'trash')}render('buyer')}
function cartDel(pid,v){S.buyer.cart=S.buyer.cart.filter(x=>!(x.pid===pid&&x.v===v));toast(L('Removed from cart','Đã xóa khỏi giỏ'),'trash');render('buyer')}
function saveLater(pid,v){const c=S.buyer.cart.find(x=>x.pid===pid&&x.v===v);S.buyer.cart.splice(S.buyer.cart.indexOf(c),1);S.buyer.later.push(c);toast(L('Saved for later','Đã để dành mua sau'));render('buyer')}
function moveToCart(i){const c=S.buyer.later.splice(i,1)[0];S.buyer.cart.push(c);render('buyer')}
B.cart=()=>{UI.tmp.only=null;const G=cartGroups();const n=cartCount();const sub=G.reduce((a,g)=>a+g.sub,0);const min=S.fees.freeShipMin;
  const line=c=>{const p=P(c.pid);return `<div class="citem"><button onclick="openP('${p.id}')">${pimg(p,300)}</button><div><div class="seller xs faint" style="letter-spacing:.06em;text-transform:uppercase">${esc(p.brand)}</div><a class="md clamp2 mt4" style="display:-webkit-box" onclick="openP('${p.id}')">${esc(pn(p))}</a><div class="xs ${p.stock<=5?'dealc':'okc'} mt4">${p.stock<=5?L(`Only ${p.stock} left`,`Chỉ còn ${p.stock}`):L('In stock','Còn hàng')}</div>${c.v?`<div class="xs muted mt4">${esc(c.v)}</div>`:''}
    <div class="row wrap g12 mt12 sm"><span class="qty"><button onclick="cartQty('${p.id}',${J(c.v)},-1)" aria-label="${L('Decrease','Giảm')}">${c.q===1?ic('trash','sm'):ic('minus','sm')}</button><span>${c.q}</span><button onclick="cartQty('${p.id}',${J(c.v)},1)" aria-label="${L('Increase','Tăng')}">${ic('plus','sm')}</button></span><a class="lnk" onclick="saveLater('${p.id}',${J(c.v)})">${L('Save for later','Để dành')}</a><a class="lnk" style="color:var(--ink-3)" onclick="cartDel('${p.id}',${J(c.v)})">${L('Remove','Xóa')}</a></div></div>
    <div class="cprice right">${priceHTML(p.price*c.q,'s')}${c.q>1?`<div class="xs faint mt4">${money(p.price)} ${L('each','mỗi cái')}</div>`:''}</div></div>`};
  if(!S.buyer.cart.length&&!S.buyer.later.length)return{tab:'cart',body:`<div class="wrapx"><div class="empty" style="padding:96px 20px"><div class="art">${ic('cart','xl')}</div><h1 class="serif" style="font-size:40px">${L('Your cart is empty','Giỏ hàng đang trống')}</h1><p class="muted">${L('Discover something from a verified business.','Khám phá sản phẩm từ các doanh nghiệp đã xác minh.')}</p><div class="row g8"><button class="btn ink lg" onclick="${gb('deals')}">${L("Shop today's deals",'Xem ưu đãi hôm nay')}</button>${S.buyer.signedIn?'':`<button class="btn lg" onclick="${gb('signin')}">${L('Sign in','Đăng nhập')}</button>`}</div></div></div>${rail(L('Recently <em>viewed</em>','Đã <em>xem</em>'),S.buyer.recent.map(P).filter(Boolean))}`};
  return{tab:'cart',body:`<div class="wrapx"><h1 class="pagetitle">${L('Your cart','Giỏ hàng')} <span class="faint" style="font-size:.5em">${n} ${L('items','sản phẩm')}</span></h1><div class="cartgrid">
   <div>${G.map(g=>{const s=SL(g.seller);const left=Math.max(0,min-g.sub);return `<div class="cgroup"><div class="cgroup-h">${mono(s,'sm')}<div class="grow"><a class="b" onclick="${gb('store',{id:s.id})}">${esc(s.name)}</a><div class="xs faint">${L('Ships from','Giao từ')} ${esc(s.city)}</div></div><div style="min-width:200px;max-width:260px;flex:1"><div class="xs ${left?'muted':'okc b'} mb8 right">${left?L(`${money(left)} away from free shipping`,`Thêm ${money(left)} để miễn phí giao`):L('✓ Free shipping unlocked','✓ Đã được miễn phí giao')}</div><div class="prog"><i style="width:${Math.min(100,g.sub/min*100)}%"></i></div></div></div>${g.items.map(line).join('')}</div>`}).join('')}
    ${S.buyer.later.length?`<h2 class="serif mt32 mb16" style="font-size:26px">${L('Saved for later','Để dành mua sau')}</h2><div class="pgrid">${S.buyer.later.map((c,i)=>{const p=P(c.pid);return `<div class="pc"><div class="media">${pimg(p,400)}</div><div class="b"><div class="t clamp2">${esc(pn(p))}</div>${priceHTML(p.price)}<button class="btn sm mt8" style="align-self:flex-start" onclick="moveToCart(${i})">${L('Move to cart','Chuyển vào giỏ')}</button></div></div>`}).join('')}</div>`:''}</div>
   <div class="sumbox"><h3>${L('Summary','Tóm tắt')}</h3><div class="sum-row"><span>${L('Subtotal','Tạm tính')} (${n})</span><span>${money(sub)}</span></div><div class="sum-row"><span>${L('Shipping','Phí giao')}</span><span>${L('Calculated at checkout','Tính khi thanh toán')}</span></div><div class="sum-row"><span>${L('Sales tax','Thuế')}</span><span>${L('Calculated at checkout','Tính khi thanh toán')}</span></div>
    <div class="sum-total"><span>${L('Estimated total','Tạm tính')}</span><span>${money(sub)}</span></div><button class="btn ink lg block mt16" onclick="goCheckout()">${L('Checkout','Thanh toán')} ${ic('chev','sm')}</button>
    <div class="assure" style="grid-template-columns:1fr">${[['lock',L('Secure checkout with Visa, Mastercard, PayPal, Apple Pay','Thanh toán an toàn: Visa, Mastercard, PayPal, Apple Pay')],['return',L('Free 30-day returns','Đổi trả miễn phí 30 ngày')]].map(([i,t])=>`<span>${ic(i)}${t}</span>`).join('')}</div></div>
  </div></div>${rail(L('Customers also <em>bought</em>','Khách cũng <em>mua</em>'),visible().filter(p=>!S.buyer.cart.some(c=>c.pid===p.id)&&!p.flag).slice(3,13))}`,sticky:`<div class="grow"><div class="xs muted">${L('Subtotal','Tạm tính')}</div><b class="md">${money(sub)}</b></div><button class="btn ink lg" onclick="goCheckout()">${L('Checkout','Thanh toán')} (${n})</button>`}};
function goCheckout(){if(!S.buyer.cart.length)return;if(!S.buyer.signedIn){go('buyer','signin',{next:'checkout'});return}go('buyer','checkout',{})}

/* ---------- Checkout ---------- */
function coCalc(){const G=cartGroups(UI.tmp.only);UI.tmp.ship=UI.tmp.ship||{};const a=curAddr();const f=S.fees;
  G.forEach(g=>{const m=UI.tmp.ship[g.seller]||'std';g.method=m;g.ship=m==='exp'?f.expShip:(g.sub>=f.freeShipMin?0:f.stdShip);g.eta=m==='exp'?etaExp():etaStd()});
  const items=G.reduce((a,g)=>a+g.sub,0),ship=G.reduce((a,g)=>a+g.ship,0);
  let promo=0;const pc=S.buyer.promo&&PROMOS[S.buyer.promo];if(pc){if(pc.type==='pct')promo=Math.min(items*pc.val/100,pc.cap||1e9);else if(items>=(pc.min||0))promo=pc.val}
  const taxable=items-promo;const tax=+(taxable*a.tax/100).toFixed(2);
  return{G,items,ship,promo,tax,total:items+ship-promo+tax,a}}
function applyPromo(){const v=($('.frame[data-role="buyer"] #promo')||{}).value;const code=(v||'').trim().toUpperCase();if(!PROMOS[code]){toast(L('That code is not valid','Mã không hợp lệ'),'alert');return}S.buyer.promo=code;toast(L('Promo applied: ','Đã áp dụng mã: ')+L(PROMOS[code].en,PROMOS[code].vi),'tag');render('buyer')}
B.checkout=()=>{if(!S.buyer.signedIn)return B.signin({next:'checkout'});const c=coCalc();if(!c.G.length)return B.cart();
  const pay=S.buyer.pay;const n=c.G.reduce((a,g)=>a+g.items.reduce((x,i)=>x+i.q,0),0);
  const sumBox=`<div class="sumbox"><h3>${L('Order summary','Tóm tắt đơn hàng')}</h3>
    ${c.G.flatMap(g=>g.items).map(i=>{const p=P(i.pid);return `<div class="row g12 mb12"><span style="width:52px;position:relative">${pimg(p,120)}<span class="bdg dark" style="position:absolute;top:-6px;right:-6px;padding:0 6px">${i.q}</span></span><span class="sm grow clamp2">${esc(pn(p))}</span><span class="sm">${money(p.price*i.q)}</span></div>`}).join('')}
    <div class="hr"></div><div class="sum-row"><span>${L('Items','Sản phẩm')} (${n})</span><span>${money(c.items)}</span></div><div class="sum-row"><span>${L('Shipping','Phí giao')}</span><span>${c.ship?money(c.ship):L('Free','Miễn phí')}</span></div>${c.promo?`<div class="sum-row"><span class="okc">${L('Promo','Khuyến mãi')} ${S.buyer.promo}</span><span class="okc">−${money(c.promo)}</span></div>`:''}
    <div class="sum-row"><span>${L('Estimated tax','Thuế ước tính')} (${c.a.state} ${c.a.tax}%)</span><span>${money(c.tax)}</span></div>
    <div class="sum-total"><span>${L('Total','Tổng cộng')}</span><span>${money(c.total)}</span></div>
    <button class="btn ink lg block mt16" onclick="placeOrder()">${ic('lock','sm')} ${L('Place order','Đặt hàng')}</button>
    <p class="xs faint mt12">${L("By placing your order you agree to EcomDemo's conditions of use and privacy notice. EcomDemo collects and remits sales tax as a marketplace facilitator.",'Khi đặt hàng, bạn đồng ý với điều khoản và chính sách của EcomDemo. EcomDemo thu và nộp thuế bán hàng thay người bán.')}</p></div>`;
  return{bare:true,body:`<div class="co-head"><button class="wordmark" onclick="${gb('cart')}">${WM}</button><span class="sm muted d-only">${L('Cart','Giỏ hàng')} → <b style="color:var(--ink)">${L('Checkout','Thanh toán')}</b> → ${L('Confirmation','Xác nhận')}</span><span class="row g4 sm muted">${ic('lock','sm')}${L('Secure checkout','Thanh toán bảo mật')}</span></div>
  <div class="co-grid"><div>
   <div class="co-step"><div class="row between start"><h3><span class="n">1</span>${L('Shipping address','Địa chỉ giao hàng')}</h3><a class="lnk sm" onclick="openAddr()">${L('Change','Thay đổi')}</a></div><div class="md mt12" style="padding-left:40px"><b>${esc(c.a.name)}</b><br><span class="muted">${esc(c.a.line1)}, ${esc(c.a.city)}, ${c.a.state} ${c.a.zip} · ${esc(c.a.phone||'')}</span></div></div>
   <div class="co-step"><h3><span class="n">2</span>${L('Payment','Thanh toán')}</h3><div class="mt16">
    ${S.buyer.cards.map(k=>`<button class="opt ${pay===k.id?'on':''}" onclick="S.buyer.pay='${k.id}';render('buyer')"><span class="rad ${pay===k.id?'on':''}"></span>${ic('card')}<span class="grow sm"><b>${k.brand} •••• ${k.last4}</b><br><span class="muted">${esc(k.name)} · ${L('Expires','Hết hạn')} ${k.exp}</span></span></button>`).join('')}
    <button class="opt ${pay==='paypal'?'on':''}" onclick="S.buyer.pay='paypal';render('buyer')"><span class="rad ${pay==='paypal'?'on':''}"></span><b style="color:#1F4E9A">PayPal</b><span class="sm muted grow">${L('Confirm on PayPal','Xác nhận trên PayPal')}</span></button>
    <button class="opt ${pay==='apple'?'on':''}" onclick="S.buyer.pay='apple';render('buyer')"><span class="rad ${pay==='apple'?'on':''}"></span><b> Pay</b><span class="sm muted grow">Apple Pay</span></button>
    <a class="lnk sm row g4 mt12" style="display:inline-flex" onclick="openCard()">${ic('plus','sm')} ${L('Add a card','Thêm thẻ')}</a>
    <div class="hr"></div><label class="label">${L('Promo or gift code','Mã khuyến mãi / quà tặng')}</label><div class="row g8" style="max-width:440px"><input class="input" id="promo" placeholder="ECOM10" value="${esc(S.buyer.promo||'')}" style="border-radius:999px"><button class="btn" onclick="applyPromo()">${L('Apply','Áp dụng')}</button></div>${S.buyer.promo?`<div class="xs okc mt8">✓ ${esc(S.buyer.promo)}: ${esc(L(PROMOS[S.buyer.promo].en,PROMOS[S.buyer.promo].vi))} · <a class="lnk" onclick="S.buyer.promo=null;render('buyer')">${L('Remove','Bỏ')}</a></div>`:`<div class="help">${L('Try ECOM10 or TET2027','Thử ECOM10 hoặc TET2027')}</div>`}
   </div></div>
   <div class="co-step"><h3><span class="n">3</span>${L('Delivery','Giao hàng')}</h3>
    ${c.G.map((g,gi)=>{const s=SL(g.seller);return `<div class="pkg"><div class="row between wrap g8"><div><h4>${L('Arrives','Dự kiến giao')} ${fmtDate(g.eta)}</h4><div class="xs muted">${L('Package','Kiện')} ${gi+1}/${c.G.length} · ${esc(s.name)}, ${esc(s.city)}</div></div><div class="row g8">${g.items.map(i=>`<span style="width:44px">${pimg(P(i.pid),100)}</span>`).join('')}</div></div>
     <div class="grid c2 mt12" style="gap:8px"><button class="opt ${g.method==='std'?'on':''}" style="margin:0" onclick="UI.tmp.ship['${g.seller}']='std';render('buyer')"><span class="rad ${g.method==='std'?'on':''}"></span><span class="sm"><b>${L('Standard','Tiêu chuẩn')} · ${g.sub>=S.fees.freeShipMin?L('Free','Miễn phí'):money(S.fees.stdShip)}</b><br><span class="muted">${dayShort(etaStd())}</span></span></button>
      <button class="opt ${g.method==='exp'?'on':''}" style="margin:0" onclick="UI.tmp.ship['${g.seller}']='exp';render('buyer')"><span class="rad ${g.method==='exp'?'on':''}"></span><span class="sm"><b>${L('Expedited','Giao nhanh')} · ${money(S.fees.expShip)}</b><br><span class="muted">${dayShort(etaExp())}</span></span></button></div></div>`}).join('')}
   </div>
  </div><div>${sumBox}</div></div>`,sticky:`<div class="grow"><div class="xs muted">${L('Total','Tổng cộng')}</div><b class="md">${money(c.total)}</b></div><button class="btn ink lg" onclick="placeOrder()">${L('Place order','Đặt hàng')}</button>`}};
function placeOrder(){const c=coCalc();if(!c.G.length)return;
  openOv('buyer',`<div class="modal" style="width:min(360px,100%)"><div class="modal-b center col" style="align-items:center;padding:36px"><div class="spinner"></div><b class="md mt12">${L('Processing your payment securely…','Đang xử lý thanh toán an toàn…')}</b><div class="xs muted">${L('Card authorized now, charged when each package ships.','Thẻ được giữ tiền ngay, chỉ trừ khi từng kiện được gửi đi.')}</div></div></div>`);
  setTimeout(()=>{const now=Date.now();const ck='C'+now;const payTxt=S.buyer.pay==='paypal'?'PayPal':S.buyer.pay==='apple'?'Apple Pay':(()=>{const k=S.buyer.cards.find(x=>x.id===S.buyer.pay);return `${k.brand} •••• ${k.last4}`})();
    c.G.forEach((g,gi)=>{const promo=c.items?+(c.promo*g.sub/c.items).toFixed(2):0;
      const o={id:orderId(ck+gi),checkout:ck,buyer:{...c.a},buyerId:'me',seller:g.seller,items:g.items.map(i=>({pid:i.pid,q:i.q,v:i.v,price:P(i.pid).price})),shipMethod:g.method,shipCost:g.ship,promo,tax:+((g.sub-promo)*c.a.tax/100).toFixed(2),created:now,status:'unshipped',carrier:null,tracking:null,log:[{t:now,k:'placed'}],returnReq:null,reviewed:{},pay:payTxt,eta:g.eta,isNew:true};
      S.orders.unshift(o);g.items.forEach(i=>{const p=P(i.pid);p.stock=Math.max(0,p.stock-i.q)});
      notify('seller',`New order <b>${o.id}</b> from ${esc(c.a.name)} · ${money(totalOf(o))}`,['order',{id:o.id}])});
    const ids=new Set(c.G.flatMap(g=>g.items.map(i=>i.pid+'|'+i.v)));S.buyer.cart=S.buyer.cart.filter(i=>!ids.has(i.pid+'|'+i.v));S.buyer.promo=null;UI.tmp.only=null;UI.ov.buyer=null;
    go('buyer','success',{checkout:ck});if(onStage('seller'))render('seller');if(onStage('admin'))render('admin')},1100)}
B.success=p=>{const os=S.orders.filter(o=>o.checkout===p.checkout);if(!os.length)return B.orders({});const a=os[0].buyer;
  return{body:`<div class="wrapx" style="max-width:980px"><div class="panel bd" style="margin-top:40px;padding:36px"><div class="ok-hero">${ic('check')}<div><h1>${L('Thank you, ','Cảm ơn bạn, ')}${esc(first())}. ${L('Your order is in.','Đơn hàng đã được đặt.')}</h1><p class="md muted mt12">${L('A confirmation is on its way to','Xác nhận đang được gửi tới')} <b style="color:var(--ink)">${esc(S.buyer.email)}</b>. ${L('Shipping to','Giao đến')} ${esc(a.line1)}, ${esc(a.city)}, ${a.state} ${a.zip}.</p></div></div>
   <div class="hr" style="margin:28px 0"></div>
   ${os.map(o=>`<div class="row g16 start wrap mb16"><div style="min-width:240px"><span class="eyebrow">${L('Arrives','Dự kiến giao')}</span><div class="serif mt4" style="font-size:24px">${fmtDate(o.eta)}</div><div class="xs muted mt4">${esc(sellerName(o.seller))} · #${o.id}</div></div><div class="row g8">${o.items.map(i=>`<span style="width:72px">${pimg(P(i.pid),160)}</span>`).join('')}</div></div>`).join('')}
   <div class="row g8 wrap mt16"><button class="btn ink lg" onclick="${gb('orders')}">${L('Track your orders','Theo dõi đơn hàng')}</button><button class="btn lg" onclick="${gb('home')}">${L('Keep shopping','Tiếp tục mua sắm')}</button></div></div>
   <div class="alert info mt16">${ic('info','sm')}<div><b>Demo tip:</b> open <b>Seller Central</b> (or the <b>Shopper + Ops</b> view) and buy a shipping label for this order. Tracking here updates right away.</div></div></div>
   ${rail(L('Pairs well <em>with</em>','Mua kèm <em>hợp</em>'),visible().filter(x=>!os.some(o=>o.items.some(i=>i.pid===x.id))&&!x.flag).slice(0,10))}`}};

/* ---------- Auth ---------- */
function authShell(inner){return `<div class="bare-shell"><div class="art">${pimg(P('c1'),1000)}<blockquote>${L('“Finally, the coffee my parents drink in Đà Lạt, delivered to Houston.”','“Cuối cùng cũng có loại cà phê ba mẹ uống ở Đà Lạt, giao tận Houston.”')}<span>— Thu H., ${L('verified buyer','người mua đã xác minh')}</span></blockquote></div><div class="form"><div class="auth-card"><button class="wordmark" style="font-size:30px" onclick="${gb('home')}">${WM}</button>${inner}</div></div></div>`}
B.signin=p=>{const step=p.step||'email';return{bare:true,body:authShell(`<h1>${L('Welcome back','Chào mừng trở lại')}</h1>
   ${step==='email'?`<label class="label">${L('Email or mobile number','Email hoặc số điện thoại')}</label><input class="input" id="em" value="${esc(S.buyer.email)}"><button class="btn ink lg block mt16" onclick="setP('buyer',{step:'pw'},true)">${L('Continue','Tiếp tục')}</button>
    <div class="divtxt">${L('or','hoặc')}</div><button class="btn lg block" onclick="doSignin()"><b style="color:#4285F4">G</b> ${L('Continue with Google','Tiếp tục với Google')}</button><button class="btn lg block mt8" onclick="doSignin()"> ${L('Continue with Apple','Tiếp tục với Apple')}</button>`
   :`<div class="sm muted mb12">${esc(S.buyer.email)} · <a class="lnk" onclick="setP('buyer',{step:'email'},true)">${L('Change','Đổi')}</a></div><div class="row between"><label class="label">${L('Password','Mật khẩu')}</label><a class="lnk xs">${L('Forgot?','Quên?')}</a></div><input class="input" type="password" value="demo-password"><button class="btn ink lg block mt16" onclick="doSignin()">${L('Sign in','Đăng nhập')}</button><label class="row g8 sm mt16"><span class="chk on">${ic('check','sm')}</span>${L('Keep me signed in','Duy trì đăng nhập')}</label>`}
   <p class="sm muted mt24">${L('New here?','Lần đầu ghé?')} <a class="lnk" onclick="${gb('register',{next:p.next||''})}">${L('Create an account','Tạo tài khoản')}</a></p>
   <p class="xs faint mt12">${L('By continuing you agree to the Conditions of Use and Privacy Notice.','Khi tiếp tục, bạn đồng ý với Điều khoản và Chính sách quyền riêng tư.')}</p>`)}};
function doSignin(){S.buyer.signedIn=true;const nx=S.r.buyer.p.next;toast(L('Signed in as ','Đã đăng nhập: ')+S.buyer.name);go('buyer',nx||'home',{})}
B.register=p=>({bare:true,body:authShell(`<h1>${L('Create your account','Tạo tài khoản')}</h1>
   <div class="field"><label class="label">${L('Full name','Họ và tên')}</label><input class="input" id="rg-n"></div>
   <div class="field"><label class="label">${L('Email or mobile number','Email hoặc số điện thoại')}</label><input class="input" id="rg-e"></div>
   <div class="field"><label class="label">${L('Password','Mật khẩu')}</label><input class="input" type="password" placeholder="${L('At least 8 characters','Ít nhất 8 ký tự')}"></div>
   <div class="field"><label class="label">${L('Preferred language','Ngôn ngữ ưu tiên')}</label><div class="grid c2" style="gap:8px">${[['en','English'],['vi','Tiếng Việt']].map(([k,l])=>`<button class="opt ${S.lang===k?'on':''}" style="margin:0" onclick="S.lang='${k}';render('buyer')"><span class="rad ${S.lang===k?'on':''}"></span>${l}</button>`).join('')}</div></div>
   <button class="btn ink lg block" onclick="const n=$('.frame[data-role=buyer] #rg-n').value.trim(),e=$('.frame[data-role=buyer] #rg-e').value.trim();if(!n||!e){toast(L('Enter your name and email','Nhập tên và email'),'alert');return}S.buyer.name=n;S.buyer.email=e;S.buyer.addresses.forEach(a=>a.name=n);doSignin()">${L('Create account','Tạo tài khoản')}</button>
   <p class="xs faint mt12">${L('We will send a one-time code to verify your email.','Chúng tôi sẽ gửi mã xác minh một lần qua email.')}</p>
   <p class="sm muted mt16">${L('Already have an account?','Đã có tài khoản?')} <a class="lnk" onclick="${gb('signin',{next:p.next||''})}">${L('Sign in','Đăng nhập')}</a> · <a class="lnk" onclick="openSell()">${L('Selling as a business?','Bán hàng với tư cách doanh nghiệp?')}</a></p>`)});

/* ---------- Account ---------- */
const crumbs=(...xs)=>`<div class="crumbs">${xs.map(([l,a])=>a?`<a onclick="${a}">${l}</a>`:`<span>${l}</span>`).join('/')}</div>`;
const ptitle=t=>`<h1 class="pagetitle" style="padding-top:8px">${t}</h1>`;
B.account=()=>{if(!S.buyer.signedIn)return B.signin({next:'account'});
  const t=(i,ti,su,act)=>`<button class="acc-tile" onclick="${act}">${ic(i)}<div><b>${ti}</b><span>${su}</span></div></button>`;
  return{tab:'account',body:`<div class="wrapx" style="max-width:1080px"><h1 class="pagetitle">${L('Hi','Chào')} ${esc(first())}<span class="faint" style="font-size:.4em;display:block;font-family:var(--sans);letter-spacing:0;margin-top:10px">${esc(S.buyer.email)}</span></h1>
  <div class="acc-grid">
   ${t('box',L('Orders','Đơn hàng'),L('Track, return, or buy again','Theo dõi, trả hàng, mua lại'),gb('orders'))}
   ${t('heart',L('Saved','Đã lưu'),L('Items you love','Sản phẩm yêu thích'),gb('lists'))}
   ${t('pin',L('Addresses','Địa chỉ'),L('Where we deliver','Nơi nhận hàng'),gb('addresses'))}
   ${t('card',L('Payments','Thanh toán'),L('Cards and wallets','Thẻ và ví'),gb('payments'))}
   ${t('lock',L('Login & security','Bảo mật'),L('Password and 2-step verification','Mật khẩu và xác minh 2 bước'),"toast(L('Two-step verification is on','Xác minh 2 bước đang bật'),'lock')")}
   ${t('globe',S.lang==='vi'?'Tiếng Việt':'English',L('Switch to Tiếng Việt','Chuyển sang English'),`setLang(S.lang==='en'?'vi':'en')`)}
   ${t('help',L('Help','Trợ giúp'),L('Chat or call in English & Tiếng Việt','Chat hoặc gọi bằng tiếng Anh & tiếng Việt'),"toast(L('Connecting you to an agent…','Đang kết nối nhân viên hỗ trợ…'),'help')")}
   ${t('store',L('Sell with us','Bán hàng'),L('Register your business','Đăng ký doanh nghiệp'),'openSell()')}
   ${t('logout',L('Sign out','Đăng xuất'),L('On this device','Trên thiết bị này'),"S.buyer.signedIn=false;toast(L('Signed out','Đã đăng xuất'),'logout');go('buyer','home')")}
  </div></div>`}};
B.addresses=()=>({tab:'account',body:`<div class="wrapx" style="max-width:1080px">${crumbs([L('Account','Tài khoản'),gb('account')],[L('Addresses','Địa chỉ')])}${ptitle(L('Addresses','Địa chỉ'))}
  <div class="addr-grid"><button class="addr-tile add" onclick="openAddAddr()">${ic('plus','xl')}${L('Add address','Thêm địa chỉ')}</button>${S.buyer.addresses.map((a,i)=>`<div class="addr-tile">${i===S.buyer.addrIdx?`<span class="bdg dark mb8" style="align-self:flex-start">${L('Default','Mặc định')}</span>`:''}<b class="md">${esc(a.name)}</b><span class="sm muted">${esc(a.line1)}</span><span class="sm muted">${esc(a.city)}, ${a.state} ${a.zip}</span><span class="sm muted">${esc(a.phone||'')}</span><div class="row g12 mt12 sm" style="margin-top:auto"><a class="lnk">${L('Edit','Sửa')}</a><a class="lnk" onclick="if(S.buyer.addresses.length>1){S.buyer.addresses.splice(${i},1);S.buyer.addrIdx=0;render('buyer')}">${L('Remove','Xóa')}</a>${i!==S.buyer.addrIdx?`<a class="lnk" onclick="S.buyer.addrIdx=${i};render('buyer')">${L('Set default','Đặt mặc định')}</a>`:''}</div></div>`).join('')}</div></div>`});
B.payments=()=>({tab:'account',body:`<div class="wrapx" style="max-width:1080px">${crumbs([L('Account','Tài khoản'),gb('account')],[L('Payments','Thanh toán')])}${ptitle(L('Payments','Thanh toán'))}
  <div class="grid c-main" style="align-items:start"><div class="panel bd"><div class="row between"><h3 class="serif" style="font-size:22px">${L('Cards & wallets','Thẻ & ví')}</h3><button class="btn sm" onclick="openCard()">${ic('plus','sm')} ${L('Add','Thêm')}</button></div>
   ${S.buyer.cards.map(k=>`<div class="opt mt12" style="align-items:center">${ic('card','lg')}<div class="grow sm"><b>${k.brand} •••• ${k.last4}</b><br><span class="muted">${esc(k.name)} · ${L('Expires','Hết hạn')} ${k.exp}</span></div>${S.buyer.pay===k.id?`<span class="bdg dark">${L('Default','Mặc định')}</span>`:`<button class="btn sm" onclick="S.buyer.pay='${k.id}';render('buyer')">${L('Make default','Đặt mặc định')}</button>`}</div>`).join('')}
   <div class="opt mt12" style="align-items:center"><b style="color:#1F4E9A;width:24px">P</b><div class="grow sm"><b>PayPal</b><br><span class="muted">${L('Link at checkout','Liên kết khi thanh toán')}</span></div></div></div>
  <div class="panel bd"><span class="eyebrow">${L('Gift card balance','Số dư thẻ quà tặng')}</span><div class="serif mt8" style="font-size:40px">$0.00</div><button class="btn sm mt12" onclick="toast(L('Gift cards are out of prototype scope','Thẻ quà tặng chưa có trong bản demo'),'gift')">${L('Redeem a gift card','Nạp thẻ quà tặng')}</button><p class="xs faint mt16">${L('Card data is tokenized by our PCI-compliant processor. We never store full card numbers.','Dữ liệu thẻ được mã hóa bởi đơn vị đạt chuẩn PCI. Chúng tôi không lưu số thẻ đầy đủ.')}</p></div></div></div>`});
B.lists=()=>{const l=S.buyer.list.map(P).filter(p=>p&&p.status==='active');return{tab:'account',body:`<div class="wrapx">${crumbs([L('Account','Tài khoản'),gb('account')],[L('Saved','Đã lưu')])}${ptitle(L('Saved items','Sản phẩm đã lưu')+` <span class="faint" style="font-size:.5em">${l.length}</span>`)}
  ${l.length?`<div class="pgrid">${l.map(p=>pcard(p)).join('')}</div>`:`<div class="empty"><div class="art">${ic('heart','xl')}</div>${L('Tap the heart on any product to save it here.','Bấm biểu tượng trái tim trên sản phẩm để lưu vào đây.')}</div>`}</div>`}};

/* ---------- Orders ---------- */
function myOrders(){return S.orders.filter(o=>o.buyerId==='me').sort((a,b)=>b.created-a.created)}
function headline(o){if(o.status==='unshipped')return `${L('Arriving','Dự kiến giao')} ${fmtDate(o.eta)}`;if(o.status==='shipped')return `<span class="okc">${L('On the way · arriving','Đang giao · dự kiến')} ${fmtDate(o.eta)}</span>`;if(o.status==='delivered')return `${L('Delivered','Đã giao')} ${fmtDate(o.delivered)}`;
  if(o.status==='return_requested'){const r=o.returnReq;return r.status==='approved'?L('Return approved · drop off by ','Đã duyệt trả hàng · gửi trước ')+dayShort(r.created+7*DAY):r.status==='rejected'?`<span class="dealc">${L('Return declined by seller','Người bán từ chối trả hàng')}</span>`:L('Return requested · waiting for seller','Đã yêu cầu trả hàng · chờ người bán')}
  if(o.status==='refunded')return L('Refunded','Đã hoàn tiền')+` ${money(o.refund||totalOf(o))}`;return L('Cancelled','Đã hủy')}
function orderActs(o,detail){const a=[];const pid=o.items[0].pid;const days=o.delivered?(Date.now()-o.delivered)/DAY:0;
  if(o.status==='shipped'&&!detail)a.push(`<button class="btn ink" onclick="${gb('order',{id:o.id})}">${L('Track package','Theo dõi kiện hàng')}</button>`);
  if(o.status==='unshipped')a.push(`<button class="btn" onclick="cancelOrder('${o.id}')">${L('Cancel order','Hủy đơn')}</button>`);
  if(o.status==='delivered'&&days<30)a.push(`<button class="btn" onclick="${gb('return',{id:o.id})}">${L('Return or replace','Trả hoặc đổi hàng')}</button>`);
  if(o.status==='delivered'&&!o.reviewed[pid])a.push(`<button class="btn" onclick="${gb('review',{id:pid,order:o.id})}">${L('Write a review','Viết đánh giá')}</button>`);
  if(o.status==='return_requested'&&o.returnReq.status==='rejected'&&!o.claim)a.push(`<button class="btn ink" onclick="fileClaim('${o.id}')">${L('File an A-to-z claim','Gửi khiếu nại A-Z')}</button>`);
  if(o.status==='return_requested'&&o.returnReq.status==='approved')a.push(`<button class="btn ink" onclick="${gb('return',{id:o.id,done:1})}">${L('Show return QR code','Xem mã QR trả hàng')}</button>`);
  if(['delivered','cancelled','refunded'].includes(o.status))a.push(`<button class="btn ${o.status==='delivered'?'':'ink'}" onclick="o_again('${o.id}')">${L('Buy again','Mua lại')}</button>`);
  if(!detail)a.push(`<button class="btn ghost" onclick="${gb('order',{id:o.id})}">${L('Order details','Chi tiết đơn')}</button>`);return a.join('')}
function o_again(id){const o=S.orders.find(x=>x.id===id);o.items.forEach(i=>{const c=S.buyer.cart.find(x=>x.pid===i.pid&&x.v===i.v);if(c)c.q+=i.q;else S.buyer.cart.push({pid:i.pid,v:i.v,q:i.q})});toast(L('Added to cart','Đã thêm vào giỏ'),'cart');go('buyer','cart')}
function cancelOrder(id){openOv('buyer',`<div class="modal">${mHead('buyer',L('Cancel this order?','Hủy đơn hàng này?'))}<div class="modal-b"><p class="sm muted">${L('It has not shipped yet, so cancelling is free. The hold on your card is released within 1–3 business days.','Đơn chưa được gửi nên bạn có thể hủy miễn phí. Khoản giữ tiền trên thẻ sẽ được hoàn trong 1–3 ngày làm việc.')}</p><label class="label mt16">${L('Reason (optional)','Lý do (không bắt buộc)')}</label><select class="select" id="cr"><option>${L('Need to change shipping address','Cần đổi địa chỉ')}</option><option>${L('Ordered by mistake','Đặt nhầm')}</option><option>${L('Found a better price','Tìm được giá tốt hơn')}</option><option>${L('Delivery is too slow','Giao quá chậm')}</option></select></div><div class="modal-f"><button class="btn" onclick="closeOv('buyer')">${L('Keep order','Giữ đơn')}</button><button class="btn ink" onclick="doCancel('${id}')">${L('Cancel order','Hủy đơn')}</button></div></div>`)}
function doCancel(id){const o=S.orders.find(x=>x.id===id);if(o.status!=='unshipped'){toast(L('This order has already shipped','Đơn đã được gửi'),'alert');closeOv('buyer');return}o.status='cancelled';o.cancelReason='Buyer: '+$('.frame[data-role="buyer"] #cr').value;o.log.unshift({t:Date.now(),k:'cancelled'});o.items.forEach(i=>P(i.pid).stock+=i.q);
  notify('seller',`Buyer cancelled order <b>${o.id}</b> before shipment`,['order',{id}]);UI.ov.buyer=null;toast(L('Order cancelled','Đã hủy đơn'));render('buyer');if(onStage('seller'))render('seller')}
B.orders=p=>{if(!S.buyer.signedIn)return B.signin({next:'orders'});const tab=p.tab||'all';const all=myOrders();
  const list=all.filter(o=>tab==='all'||(tab==='open'&&['unshipped','shipped'].includes(o.status))||(tab==='returns'&&['return_requested','refunded'].includes(o.status))||(tab==='cancelled'&&o.status==='cancelled')).filter(o=>!p.q||o.items.some(i=>norm(pn(P(i.pid))).includes(norm(p.q)))||o.id.includes(p.q||'#'));
  const T=[['all',L('All orders','Tất cả')],['open',L('On the way','Đang giao')],['returns',L('Returns','Trả hàng')],['cancelled',L('Cancelled','Đã hủy')]];
  return{tab:'account',body:`<div class="wrapx" style="max-width:1080px">${crumbs([L('Account','Tài khoản'),gb('account')],[L('Orders','Đơn hàng')])}
  <div class="row between wrap g12"><h1 class="pagetitle" style="padding:8px 0 0">${L('Your orders','Đơn hàng của bạn')}</h1><form class="sbar" style="max-width:320px;height:42px;flex:1" onsubmit="event.preventDefault();setP('buyer',{q:this.q.value})">${ic('search','sm')}<input name="q" value="${esc(p.q||'')}" placeholder="${L('Search orders','Tìm đơn hàng')}"></form></div>
  <div class="chips mt24 mb16">${T.map(([k,l])=>`<button class="chip ${tab===k?'on':''}" onclick="go('buyer','orders',{tab:'${k}'},true)">${l}</button>`).join('')}</div>
  ${list.map(o=>`<div class="ocard"><div class="ocard-h"><div>${L('Placed','Ngày đặt')}<b>${fmtDate(o.created,{month:'short',day:'numeric',year:'numeric'})}</b></div><div>${L('Total','Tổng')}<b>${money(totalOf(o))}</b></div><div class="d-only">${L('Ship to','Giao đến')}<b>${esc(o.buyer.name)}</b></div><div style="margin-left:auto;text-align:right">${L('Order','Mã đơn')}<b class="tnum">#${o.id}</b></div></div>
   <div class="ocard-b"><div><h3>${headline(o)}</h3>${o.status==='shipped'?`<div class="sm muted mt4">${esc(o.carrier)} · ${esc(o.tracking)}</div>`:''}${o.items.map(i=>{const x=P(i.pid);return `<div class="oitem"><button onclick="openP('${x.id}')">${pimg(x,200)}</button><div class="sm"><a class="md clamp2" style="display:-webkit-box" onclick="openP('${x.id}')">${esc(pn(x))}</a><div class="xs faint mt4">${esc(sellerName(o.seller))}${i.v?' · '+esc(i.v):''}${i.q>1?` · ${L('Qty','SL')} ${i.q}`:''}</div>${o.status==='delivered'?`<div class="xs muted mt4">${L('Returnable until','Đổi trả đến')} ${shortDate(o.delivered+30*DAY)}</div>`:''}</div></div>`}).join('')}</div>
   <div class="oacts">${orderActs(o)}</div></div></div>`).join('')||`<div class="empty"><div class="art">${ic('box','xl')}</div>${L('No orders here yet.','Chưa có đơn hàng.')}<button class="btn ink" onclick="${gb('home')}">${L('Start shopping','Bắt đầu mua sắm')}</button></div>`}</div>`}};
B.order=p=>{const o=S.orders.find(x=>x.id===p.id);if(!o)return B.orders({});const s=SL(o.seller);
  const stage={unshipped:0,shipped:1,delivered:3,return_requested:3,refunded:3,cancelled:0}[o.status];const out=o.status==='shipped'&&o.log.some(l=>l.k==='out');const k=out?2:stage;
  const steps=[L('Ordered','Đã đặt'),L('Shipped','Đã gửi'),L('Out for delivery','Đang giao'),L('Delivered','Đã giao')];
  return{tab:'account',body:`<div class="wrapx" style="max-width:1080px">${crumbs([L('Account','Tài khoản'),gb('account')],[L('Orders','Đơn hàng'),gb('orders')],['#'+o.id])}
  <h1 class="pagetitle" style="padding-top:8px">${headline(o)}</h1>
  <div class="grid c-main" style="align-items:start;gap:24px"><div class="col" style="gap:16px">
   <div class="panel bd">${o.status!=='cancelled'?`<div class="track" style="margin-top:4px"><div class="fill" style="width:${k/3*75}%"></div>${steps.map((t,i)=>`<div class="st ${i<=k?'done':''}"><i>${i<=k?ic('check','sm').replace('class="ic sm"','class="ic sm" style="color:#fff;width:12px;height:12px;stroke-width:3"'):''}</i>${t}</div>`).join('')}</div>`:''}
    ${o.tracking?`<div class="sm mt16 muted">${L('Carrier','Đơn vị vận chuyển')} <b style="color:var(--ink)">${esc(o.carrier)}</b> · ${L('Tracking','Mã vận đơn')} <b class="tnum" style="color:var(--ink)">${esc(o.tracking)}</b></div>`:''}
    ${o.status==='shipped'?`<div class="alert warn mt16">${ic('info','sm')}<div class="grow"><b>Demo control:</b> simulate the carrier's scan events.</div><button class="btn sm" onclick="simDeliver('${o.id}')">${out?'Mark delivered':'Out for delivery'}</button></div>`:''}
    <div class="hr"></div>${o.items.map(i=>{const x=P(i.pid);return `<div class="oitem" style="margin-top:0;margin-bottom:14px"><button onclick="openP('${x.id}')">${pimg(x,200)}</button><div class="sm grow"><a class="md clamp2" style="display:-webkit-box" onclick="openP('${x.id}')">${esc(pn(x))}</a><div class="xs faint mt4"><a onclick="${gb('store',{id:s.id})}">${esc(s.name)}</a>${i.v?' · '+esc(i.v):''} · ${L('Qty','SL')} ${i.q}</div><div class="b mt8">${money(i.price)}</div></div></div>`}).join('')}<div class="oacts" style="flex-direction:row;flex-wrap:wrap">${orderActs(o,true)}</div></div>
   ${o.returnReq?`<div class="panel bd"><span class="eyebrow">${L('Return','Trả hàng')}</span><div class="md mt8">${esc(RET_REASONS.find(r=>r[0]===o.returnReq.reason)?.[S.lang==='vi'?2:1]||o.returnReq.reason)}</div><div class="sm muted">${esc(o.returnReq.comment||'')}</div><div class="mt12">${{requested:`<span class="bdg warn">${L('Waiting for seller (48 h)','Chờ người bán (48 giờ)')}</span>`,approved:`<span class="bdg ok">${L('Approved · QR code issued','Đã duyệt · đã cấp mã QR')}</span>`,rejected:`<span class="bdg err">${L('Declined','Bị từ chối')}</span>`,refunded:`<span class="bdg ok">${L('Refunded','Đã hoàn tiền')}</span>`}[o.returnReq.status]}${o.claim?` <span class="bdg info">${L('A-to-z claim','Khiếu nại A-Z')} ${o.claim}</span>`:''}</div>${o.returnReq.sellerNote?`<div class="sm muted mt12">${L('Seller','Người bán')}: “${esc(o.returnReq.sellerNote)}”</div>`:''}</div>`:''}
  </div>
  <div class="col" style="gap:16px"><div class="panel bd"><span class="eyebrow">${L('Summary','Tóm tắt')}</span><div class="mt12"><div class="sum-row"><span>${L('Items','Sản phẩm')}</span><span>${money(subOf(o))}</span></div><div class="sum-row"><span>${L('Shipping','Phí giao')}</span><span>${money(o.shipCost)}</span></div>${o.promo?`<div class="sum-row"><span>${L('Promo','Khuyến mãi')}</span><span>−${money(o.promo)}</span></div>`:''}<div class="sum-row"><span>${L('Tax','Thuế')}</span><span>${money(o.tax)}</span></div><div class="sum-total"><span>${L('Total','Tổng')}</span><span>${money(totalOf(o))}</span></div>${o.refund?`<div class="sum-row okc mt8"><span>${L('Refunded','Đã hoàn')}</span><span>${money(o.refund)}</span></div>`:''}</div>
    <div class="hr"></div><div class="sm"><b>${L('Ship to','Giao đến')}</b><div class="muted">${esc(o.buyer.name)}, ${esc(o.buyer.line1)}, ${esc(o.buyer.city)}, ${o.buyer.state} ${o.buyer.zip}</div></div><div class="sm mt12"><b>${L('Payment','Thanh toán')}</b><div class="muted">${esc(o.pay)}</div></div></div>
   <div class="panel bd"><span class="eyebrow">${L('History','Lịch sử')}</span><div class="tl mt16">${o.log.map(l=>`<div><b>${L(LOGTXT[l.k][0],LOGTXT[l.k][1])}</b><div class="xs muted">${new Date(l.t).toLocaleString(LOC(),{weekday:'short',month:'short',day:'numeric',hour:'numeric',minute:'2-digit'})}${l.k==='transit'?' · '+(SL(o.seller).city):''}${l.k==='delivered'?' · '+esc(o.buyer.city)+', '+o.buyer.state:''}</div></div>`).join('')}</div></div></div></div></div>`}};
function simDeliver(id){const o=S.orders.find(x=>x.id===id);const out=o.log.some(l=>l.k==='out');
  if(!out){o.log.unshift({t:Date.now(),k:'out'});toast(L('Out for delivery','Đang giao đến bạn'),'truck')}
  else{o.status='delivered';o.delivered=Date.now();o.log.unshift({t:Date.now(),k:'delivered'});notify('seller',`Order <b>${o.id}</b> was delivered`,['order',{id}]);toast(L('Delivered','Đã giao hàng'))}
  render('buyer');if(onStage('seller'))render('seller')}

/* ---------- Returns ---------- */
const RET_REASONS=[['defective','Item defective or doesn\'t work','Sản phẩm lỗi hoặc không hoạt động'],['not_described','Not as described','Không đúng mô tả'],['wrong','Wrong item was sent','Giao sai sản phẩm'],['damaged','Arrived damaged','Hàng bị hư hỏng khi nhận'],['fit','Doesn\'t fit','Không vừa'],['no_need','No longer needed','Không còn nhu cầu']];
B.return=p=>{const o=S.orders.find(x=>x.id===p.id);if(!o)return B.orders({});
  if(p.done||(o.returnReq&&o.returnReq.status==='approved')){const ap=o.returnReq&&o.returnReq.status==='approved';return{tab:'account',body:`<div class="wrapx" style="max-width:880px"><div class="panel bd" style="margin-top:40px;padding:36px"><div class="ok-hero">${ic('check')}<div><h1>${ap?L('Your return is approved','Yêu cầu trả hàng đã được duyệt'):L('Return request sent','Đã gửi yêu cầu trả hàng')}</h1><p class="md muted mt12">${ap?L('Show this QR code at any UPS Store. No box or label needed.','Đưa mã QR này tại bất kỳ UPS Store nào, không cần hộp hay nhãn.'):L('The seller has 48 hours to respond. If they don\'t, it is approved automatically.','Người bán có 48 giờ để phản hồi. Nếu không, yêu cầu sẽ tự động được duyệt.')}</p></div></div>
   ${ap?`<div class="row g24 wrap mt24"><div class="qr"></div><div class="md"><span class="eyebrow">${L('Drop off by','Gửi trước ngày')}</span><div class="serif mt4" style="font-size:26px">${fmtDate(o.returnReq.created+7*DAY)}</div><div class="sm muted mt12">${L('Return code','Mã trả hàng')} <b style="color:var(--ink)">RMA-${o.id.slice(-6)}</b><br>${L('Refund','Hoàn tiền')} <b style="color:var(--ink)">${money(subOf(o)+o.tax)}</b> ${L('to','về')} ${esc(o.pay)}<br>${L('Issued when the carrier scans your package.','Hoàn khi đơn vị vận chuyển quét kiện hàng.')}</div></div></div>`:''}
   <div class="row g8 mt24"><button class="btn ink" onclick="${gb('orders',{tab:'returns'})}">${L('View your returns','Xem các yêu cầu trả hàng')}</button><button class="btn" onclick="${gb('home')}">${L('Keep shopping','Tiếp tục mua sắm')}</button></div></div></div>`}}
  const sel=UI.tmp.retSel||o.items.map(i=>i.pid);const reason=UI.tmp.retR||'';
  return{tab:'account',body:`<div class="wrapx" style="max-width:880px">${crumbs([L('Orders','Đơn hàng'),gb('orders')],[L('Return','Trả hàng')])}${ptitle(L('Start a return','Bắt đầu trả hàng'))}
  <div class="panel bd">${o.items.map(i=>{const x=P(i.pid);const on=sel.includes(i.pid);return `<button class="opt ${on?'on':''}" onclick="const s=UI.tmp.retSel||${J(o.items.map(i=>i.pid))};const k=s.indexOf('${i.pid}');k<0?s.push('${i.pid}'):s.splice(k,1);UI.tmp.retSel=s;render('buyer')"><span class="chk ${on?'on':''}">${on?ic('check','sm'):''}</span><span style="width:60px;flex:none">${pimg(x,140)}</span><span class="sm grow"><b class="clamp2">${esc(pn(x))}</b><span class="muted">${money(i.price)} · ${L('Qty','SL')} ${i.q}</span></span></button>`}).join('')}
   <div class="field mt24"><label class="label">${L('Why are you returning it?','Lý do trả hàng?')}</label><select class="select" onchange="UI.tmp.retR=this.value;render('buyer')"><option value="">${L('Choose a reason','Chọn lý do')}</option>${RET_REASONS.map(r=>`<option value="${r[0]}" ${reason===r[0]?'selected':''}>${L(r[1],r[2])}</option>`).join('')}</select></div>
   ${['defective','not_described','wrong','damaged'].includes(reason)?`<div class="alert info mb16">${ic('info','sm')}<div>${L('This is a seller issue, so return shipping is free and you get a full refund including tax.','Lỗi thuộc về người bán: miễn phí gửi trả và hoàn tiền đầy đủ cả thuế.')}</div></div>`:reason?`<div class="alert info mb16">${ic('info','sm')}<div>${L('Free drop-off at any UPS Store within 30 days.','Gửi trả miễn phí tại UPS Store trong vòng 30 ngày.')}</div></div>`:''}
   <div class="field"><label class="label">${L('Anything else? (optional)','Ghi chú thêm (không bắt buộc)')}</label><textarea class="textarea" id="rcom"></textarea></div>
   <div class="field"><label class="label">${L('Return method','Cách gửi trả')}</label><div class="opt on"><span class="rad on"></span><span class="sm"><b>${L('UPS Store drop-off · Free','Gửi tại UPS Store · Miễn phí')}</b><br><span class="muted">${L('No box or label. Nearest: 9191 Bolsa Ave, Westminster (0.4 mi)','Không cần hộp hay nhãn. Gần nhất: 9191 Bolsa Ave, Westminster (0,6 km)')}</span></span></div></div>
   <div class="row between wrap g12 mt24"><div class="md">${L('Refund','Hoàn tiền')} <b class="serif" style="font-size:24px">${money(o.items.filter(i=>sel.includes(i.pid)).reduce((a,i)=>a+i.price*i.q,0)*(1+o.buyer.tax/100))}</b> <span class="sm muted">${L('to','về')} ${esc(o.pay)}</span></div><button class="btn ink lg" ${!reason||!sel.length?'disabled':''} onclick="submitReturn('${o.id}')">${L('Submit return','Gửi yêu cầu')}</button></div></div></div>`}};
function submitReturn(id){const o=S.orders.find(x=>x.id===id);o.status='return_requested';o.returnReq={reason:UI.tmp.retR,comment:($('.frame[data-role="buyer"] #rcom')||{}).value||'',status:'requested',created:Date.now(),items:UI.tmp.retSel||o.items.map(i=>i.pid),method:'ups'};o.log.unshift({t:Date.now(),k:'return_requested'});
  UI.tmp.retSel=null;UI.tmp.retR=null;notify('seller',`Return requested for order <b>${o.id}</b>. Respond within 48 hours.`,['returns',{}]);toast(L('Return request sent to the seller','Đã gửi yêu cầu trả hàng'),'return');go('buyer','return',{id,done:1});if(onStage('seller'))render('seller')}
function fileClaim(id){openOv('buyer',`<div class="modal">${mHead('buyer',L('A-to-z Guarantee claim','Khiếu nại Bảo đảm A-Z'))}<div class="modal-b"><p class="sm muted">${L('If a seller declines a valid return, EcomDemo steps in. Our team decides within 2 business days.','Nếu người bán từ chối một yêu cầu hợp lệ, EcomDemo sẽ can thiệp và quyết định trong 2 ngày làm việc.')}</p><div class="field mt16"><label class="label">${L('What happened?','Chuyện gì đã xảy ra?')}</label><textarea class="textarea" id="clm">${L('Seller declined my return, but the item is defective.','Người bán từ chối trả hàng nhưng sản phẩm bị lỗi.')}</textarea></div></div><div class="modal-f"><button class="btn" onclick="closeOv('buyer')">${L('Cancel','Hủy')}</button><button class="btn ink" onclick="doClaim('${id}')">${L('Submit claim','Gửi khiếu nại')}</button></div></div>`)}
function doClaim(id){const o=S.orders.find(x=>x.id===id);const cid='AZ-'+(20420+S.claims.length);S.claims.unshift({id:cid,order:o.id,seller:o.seller,buyer:o.buyer.name,reason:'Return declined by seller',detail:$('.frame[data-role="buyer"] #clm').value,amount:+(subOf(o)+o.tax).toFixed(2),status:'open',created:Date.now(),sellerResp:o.returnReq.sellerNote||null});o.claim=cid;o.log.unshift({t:Date.now(),k:'claim'});
  notify('admin',`New A-to-z claim <b>${cid}</b> on order ${o.id}`,['claims',{}]);notify('seller',`A-to-z claim <b>${cid}</b> filed on order ${o.id}`,['returns',{}]);UI.ov.buyer=null;toast(L('Claim submitted. We will email you within 2 business days.','Đã gửi khiếu nại, chúng tôi sẽ phản hồi trong 2 ngày làm việc.'),'shield');render('buyer');renderAll()}

/* ---------- Review ---------- */
B.review=p=>{const x=P(p.id);const st=UI.tmp.rs||0;return{tab:'account',body:`<div class="wrapx" style="max-width:780px">${crumbs([L('Orders','Đơn hàng'),gb('orders')],[L('Review','Đánh giá')])}${ptitle(L('How was it?','Sản phẩm thế nào?'))}
  <div class="panel bd"><div class="row g12">${`<span style="width:64px">${pimg(x,140)}</span>`}<span class="md">${esc(pn(x))}</span></div><div class="hr"></div>
   <label class="label">${L('Overall rating','Đánh giá chung')}</label><div class="starpick" role="radiogroup">${[1,2,3,4,5].map(n=>`<button class="${n<=st?'on':''}" onclick="UI.tmp.rs=${n};render('buyer')" aria-label="${n} stars">★</button>`).join('')}</div>
   <label class="label mt24">${L('Headline','Tiêu đề')}</label><input class="input" id="rv-t" placeholder="${L("What's most important to know?",'Điều quan trọng nhất là gì?')}">
   <label class="label mt16">${L('Your review','Nội dung đánh giá')}</label><textarea class="textarea" id="rv-b" placeholder="${L('What did you like or dislike?','Bạn thích hoặc không thích điểm nào?')}"></textarea>
   <button class="drop mt16" style="width:100%;padding:20px" onclick="toast(L('Photo attached (demo)','Đã đính kèm ảnh (demo)'),'camera')">${ic('camera','lg')}<span class="sm mt8">${L('Add photos or video','Thêm ảnh hoặc video')}</span></button>
   <p class="xs faint mt12">${L('Write in English or Tiếng Việt. Other shoppers can translate your review.','Bạn có thể viết bằng tiếng Anh hoặc tiếng Việt, người khác có thể dịch đánh giá của bạn.')}</p>
   <div class="right mt16"><button class="btn ink lg" onclick="submitReview('${x.id}','${p.order||''}')">${L('Submit review','Gửi đánh giá')}</button></div></div></div>`}};
function submitReview(pid,oid){const st=UI.tmp.rs;if(!st){toast(L('Choose a star rating','Hãy chọn số sao'),'alert');return}const t=$('.frame[data-role="buyer"] #rv-t').value.trim()||L('Review','Đánh giá'),b=$('.frame[data-role="buyer"] #rv-b').value.trim()||'—';const vi=S.lang==='vi';
  S.reviews.unshift({id:pid+'-u'+Date.now(),pid,name:S.buyer.name.split(' ')[0]+' '+S.buyer.name.split(' ').slice(-1)[0][0]+'.',stars:st,title:t,titleVi:t,text:b,textVi:b,days:0,helpful:0,verified:true,lang:vi?'vi':'en'});
  const x=P(pid);x.rating=+((x.rating*x.reviews+st)/(x.reviews+1)).toFixed(1);x.reviews++;
  const o=oid?S.orders.find(z=>z.id===oid):S.orders.find(z=>z.buyerId==='me'&&z.items.some(i=>i.pid===pid));if(o)o.reviewed[pid]=true;
  UI.tmp.rs=0;toast(L('Review submitted. Thank you!','Đã gửi đánh giá, cảm ơn bạn!'),'star');go('buyer','product',{id:pid})}

/* ---------- Overlays ---------- */
function openAddr(){openOv('buyer',()=>`<div class="modal" style="width:min(460px,100%)">${mHead('buyer',L('Deliver to','Giao đến'))}<div class="modal-b"><p class="sm muted mb16">${L('Delivery dates and sales tax depend on the address.','Ngày giao và thuế phụ thuộc vào địa chỉ.')}</p>
  ${S.buyer.addresses.map((a,i)=>`<button class="opt ${i===S.buyer.addrIdx?'on':''}" onclick="S.buyer.addrIdx=${i};closeOv('buyer')"><span class="rad ${i===S.buyer.addrIdx?'on':''}"></span><span class="sm"><b>${esc(a.name)}</b><br><span class="muted">${esc(a.line1)}, ${esc(a.city)}, ${a.state} ${a.zip} · ${L('tax','thuế')} ${a.tax}%</span></span></button>`).join('')}
  <button class="btn block mt16" onclick="openAddAddr()">${ic('plus','sm')} ${L('Add an address','Thêm địa chỉ')}</button></div></div>`)}
function openAddAddr(){openOv('buyer',`<div class="modal">${mHead('buyer',L('New address','Địa chỉ mới'))}<div class="modal-b">
  <div class="field"><label class="label">${L('Full name','Họ tên')}</label><input class="input" id="ad-n" value="${esc(S.buyer.name)}"></div>
  <div class="field"><label class="label">${L('Phone','Số điện thoại')}</label><input class="input" id="ad-p" placeholder="(000) 000-0000"></div>
  <div class="field"><label class="label">${L('Street address','Địa chỉ')}</label><input class="input" id="ad-l" placeholder="${L('Street address or P.O. Box','Số nhà, tên đường')}"></div>
  <div class="grid c3" style="gap:10px"><div class="field"><label class="label">${L('City','Thành phố')}</label><input class="input" id="ad-c" value="San Jose"></div><div class="field"><label class="label">${L('State','Bang')}</label><select class="select" id="ad-s">${[['CA',9.375],['TX',8.25],['WA',10.25],['VA',6],['NY',8.875],['FL',7],['GA',8.9]].map(([s,t])=>`<option value="${s}|${t}">${s}</option>`).join('')}</select></div><div class="field"><label class="label">ZIP</label><input class="input" id="ad-z" value="95122" inputmode="numeric"></div></div></div>
  <div class="modal-f"><button class="btn" onclick="closeOv('buyer')">${L('Cancel','Hủy')}</button><button class="btn ink" onclick="saveAddr()">${L('Save address','Lưu địa chỉ')}</button></div></div>`)}
function saveAddr(){const g=id=>$(`.frame[data-role="buyer"] #${id}`).value;const l=g('ad-l').trim();if(!l){toast(L('Enter a street address','Nhập địa chỉ'),'alert');return}const [st,tx]=g('ad-s').split('|');
  S.buyer.addresses.push({name:g('ad-n')||S.buyer.name,line1:l,city:g('ad-c'),state:st,zip:g('ad-z'),phone:g('ad-p'),tax:+tx});S.buyer.addrIdx=S.buyer.addresses.length-1;UI.ov.buyer=null;toast(L('Address saved and verified with USPS','Đã lưu và xác thực địa chỉ với USPS'),'pin');render('buyer')}
function openCard(){openOv('buyer',`<div class="modal" style="width:min(480px,100%)">${mHead('buyer',L('Add a card','Thêm thẻ'))}<div class="modal-b">
  <div class="field"><label class="label">${L('Card number','Số thẻ')}</label><input class="input" id="cd-n" value="4000 0566 5566 5556" inputmode="numeric"></div>
  <div class="field"><label class="label">${L('Name on card','Tên trên thẻ')}</label><input class="input" value="${esc(S.buyer.name)}" id="cd-h"></div>
  <div class="grid c2" style="gap:10px"><div class="field"><label class="label">${L('Expiry','Hết hạn')}</label><input class="input" value="11/29"></div><div class="field"><label class="label">CVV</label><input class="input" value="123" type="password"></div></div>
  <p class="xs faint row g4">${ic('lock','sm')} ${L('Card details go straight to our PCI-compliant processor.','Thông tin thẻ đi thẳng tới đơn vị xử lý đạt chuẩn PCI.')}</p></div>
  <div class="modal-f"><button class="btn" onclick="closeOv('buyer')">${L('Cancel','Hủy')}</button><button class="btn ink" onclick="const n=$('.frame[data-role=buyer] #cd-n').value.replace(/\\D/g,'');S.buyer.cards.push({id:'c'+Date.now(),brand:n[0]==='5'?'Mastercard':n[0]==='3'?'Amex':'Visa',last4:n.slice(-4),exp:'11/29',name:$('.frame[data-role=buyer] #cd-h').value});S.buyer.pay=S.buyer.cards[S.buyer.cards.length-1].id;UI.ov.buyer=null;toast(L('Card added','Đã thêm thẻ'),'card');render('buyer')">${L('Add card','Thêm thẻ')}</button></div></div>`)}
function openMenu(){openOv('buyer',()=>`<div class="drawer"><div class="drawer-h"><span class="wordmark">${WM}</span><span class="grow"></span><button class="iconbtn" onclick="closeOv('buyer')" aria-label="Close">${ic('x')}</button></div>
  <div class="grp"><span class="eyebrow">${L('Shop','Mua sắm')}</span></div><button class="itm" onclick="${gb('deals')}">${L("Today's deals",'Ưu đãi hôm nay')}</button><button class="itm" onclick="openP('f3')">${L('Lunar New Year gifting','Quà Tết')}</button>${CATS.map(c=>`<button class="itm" onclick="${gb('search',{cat:c.id})}">${cn(c)}<span class="grow"></span>${ic('chev','sm')}</button>`).join('')}
  <div class="grp"><span class="eyebrow">${L('Account','Tài khoản')}</span></div><button class="itm" onclick="${gb('account')}">${ic('user')} ${S.buyer.signedIn?esc(S.buyer.name):L('Sign in','Đăng nhập')}</button><button class="itm" onclick="${gb('orders')}">${ic('box')} ${L('Orders','Đơn hàng')}</button><button class="itm" onclick="setLang(S.lang==='en'?'vi':'en')">${ic('globe')} ${S.lang==='en'?'Tiếng Việt':'English'}</button><button class="itm" onclick="openSell()">${ic('store')} ${L('Sell on EcomDemo','Bán hàng trên EcomDemo')}</button></div>`,{left:true})}
